-- ===== supabase/migrations/20261026000001_core.sql
-- District Five Law Enforcement Hub: core schema (Stage 1)
-- Roleplay community hub. All operational records are fictional.
--
-- Access model
--   * Every table has row-level security. Browser clients never write tables
--     directly; consequential changes go through the SECURITY DEFINER
--     functions in 20261026000002_functions.sql, which check authority.
--   * "Active membership" is the unit of access. Suspending or removing a
--     membership revokes access without deleting history.
--   * Technical administration (profiles.is_admin) is separate from the
--     authority to read confidential personnel records.

create extension if not exists btree_gist;

-- ---------------------------------------------------------------- enums

create type public.tier as enum (
  'probationary', 'patrol', 'supervisor', 'high_command', 'department_head', 'dps'
);

create type public.membership_status as enum ('pending', 'active', 'suspended', 'removed', 'denied');

create type public.duty_status as enum ('off_duty', 'on_duty', 'unavailable');

create type public.approval_status as enum (
  'draft', 'submitted', 'under_review', 'returned', 'approved', 'denied', 'withdrawn', 'archived'
);

create or replace function public.tier_rank(t public.tier)
returns int language sql immutable as $$
  select case t
    when 'probationary' then 1
    when 'patrol' then 2
    when 'supervisor' then 3
    when 'high_command' then 4
    when 'department_head' then 5
    when 'dps' then 6
  end
$$;

-- ---------------------------------------------------------- configuration

create table public.departments (
  key text primary key check (key ~ '^[a-z0-9_]{2,12}$'),
  name text not null,
  short_name text not null,
  kind text not null default 'department' check (kind in ('department', 'oversight')),
  tagline text,
  public_blurb text,
  accent text not null default '#8a94a6',
  quota_minutes int not null default 240 check (quota_minutes between 0 and 10080),
  week_starts_on int not null default 1 check (week_starts_on between 0 and 6),
  timezone text not null default 'America/New_York',
  bodycam_required boolean not null default false,
  bodycam_policy_text text,
  bodycam_policy_url text,
  sort_order int not null default 0,
  active boolean not null default true
);

-- Department rank ladders mapped to shared tiers. Values are configurable;
-- seed rows are marked is_sample until an administrator confirms them.
create table public.ranks (
  id uuid primary key default gen_random_uuid(),
  department_key text not null references public.departments(key),
  name text not null,
  abbreviation text,
  tier public.tier not null,
  sort_order int not null default 0,
  is_sample boolean not null default true,
  active boolean not null default true,
  unique (department_key, name)
);

-- Which tier must review a record, by record type, department and submitter tier.
-- department_key null = district-wide default.
create table public.approval_routes (
  id uuid primary key default gen_random_uuid(),
  record_type text not null,
  department_key text references public.departments(key),
  submitter_tier public.tier not null,
  required_tier public.tier not null,
  unique nulls not distinct (record_type, department_key, submitter_tier)
);

create table public.app_settings (
  key text primary key,
  value jsonb not null,
  updated_at timestamptz not null default now()
);

-- ------------------------------------------------------ people and roster

create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  display_name text not null,
  discord_id text,
  discord_username text,
  psn_id text,
  avatar_url text,
  active_department text references public.departments(key),
  is_admin boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create sequence public.ref_membership;
create sequence public.ref_shift;
create sequence public.ref_announcement;
create sequence public.ref_policy;
create sequence public.ref_personnel;

create table public.memberships (
  id uuid primary key default gen_random_uuid(),
  ref text not null unique default ('D5-MB-' || lpad(nextval('public.ref_membership')::text, 4, '0')),
  profile_id uuid references public.profiles(id),
  display_name text not null,
  department_key text not null references public.departments(key),
  rank_id uuid references public.ranks(id),
  rank_name text,
  tier public.tier not null default 'probationary',
  callsign text,
  badge text,
  status public.membership_status not null default 'pending',
  is_probationary boolean not null default true,
  probation_phase text,
  join_date date,
  supervisor_id uuid references public.memberships(id),
  training_officer_id uuid references public.memberships(id),
  subdivisions text[] not null default '{}',
  duty_status public.duty_status not null default 'off_duty',
  duty_changed_at timestamptz,
  leave_until date,
  can_view_personnel boolean not null default false,
  request_note text,
  is_demo boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- One membership per person per department (pending/active/suspended).
create unique index memberships_one_per_department
  on public.memberships (profile_id, department_key)
  where profile_id is not null and status in ('pending', 'active', 'suspended');
create index memberships_department_status on public.memberships (department_key, status);

-- Confidential personnel history. Readable only by explicitly authorized command.
create table public.personnel_records (
  id uuid primary key default gen_random_uuid(),
  ref text not null unique default ('D5-PR-' || lpad(nextval('public.ref_personnel')::text, 4, '0')),
  membership_id uuid not null references public.memberships(id),
  department_key text not null references public.departments(key),
  category text not null check (category in (
    'promotion', 'demotion', 'rank_change', 'status_change', 'transfer', 'commendation',
    'disciplinary', 'note', 'certification', 'leave', 'roster_change')),
  title text not null,
  detail text,
  before_value jsonb,
  after_value jsonb,
  effective_date date not null default current_date,
  created_by uuid references public.profiles(id),
  created_by_name text,
  created_at timestamptz not null default now()
);

-- ------------------------------------------------------------ shift logs

create table public.shift_logs (
  id uuid primary key default gen_random_uuid(),
  ref text not null unique default ('D5-SH-' || lpad(nextval('public.ref_shift')::text, 5, '0')),
  profile_id uuid not null references public.profiles(id),
  membership_id uuid not null references public.memberships(id),
  department_key text not null references public.departments(key),
  -- identity snapshot at submission; later promotions never rewrite it
  snapshot_name text not null,
  snapshot_rank text,
  snapshot_tier public.tier not null,
  snapshot_callsign text,
  snapshot_badge text,
  started_at timestamptz not null,
  ended_at timestamptz not null,
  break_minutes int not null default 0 check (break_minutes between 0 and 480),
  duration_minutes int not null check (duration_minutes between 1 and 960),
  week_start date not null,
  activity_type text not null check (activity_type in (
    'patrol', 'traffic', 'training', 'administrative', 'special_assignment', 'supervision')),
  summary text not null default '' check (length(summary) <= 4000),
  cad_reference text check (length(cad_reference) <= 80),
  recording_url text check (recording_url is null or recording_url ~* '^https?://'),
  bodycam_status text not null default 'not_required' check (bodycam_status in (
    'recorded', 'unavailable', 'not_applicable', 'not_required')),
  bodycam_explanation text,
  status public.approval_status not null default 'draft',
  required_tier public.tier not null default 'supervisor',
  assigned_to uuid references public.profiles(id),
  submitted_at timestamptz,
  decided_at timestamptz,
  decided_by uuid references public.profiles(id),
  decided_by_name text,
  decision_reason text,
  version int not null default 1,
  is_demo boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (ended_at > started_at)
);

create index shift_logs_profile_week on public.shift_logs (profile_id, week_start);
create index shift_logs_department_status on public.shift_logs (department_key, status, submitted_at);

-- Time a person logs can never overlap itself, in any department.
-- Withdrawn, denied and archived entries release their time.
alter table public.shift_logs add constraint shift_logs_no_overlap
  exclude using gist (
    profile_id with =,
    tstzrange(started_at, ended_at, '[)') with &&
  ) where (status not in ('withdrawn', 'denied', 'archived'));

-- Generic approval timeline used by every request type.
create table public.approval_actions (
  id uuid primary key default gen_random_uuid(),
  record_type text not null,
  record_id uuid not null,
  record_ref text,
  department_key text references public.departments(key),
  submitter_id uuid references public.profiles(id),
  actor_id uuid references public.profiles(id),
  actor_name text,
  actor_tier public.tier,
  action text not null check (action in (
    'created', 'submitted', 'resubmitted', 'claimed', 'assigned', 'approved', 'denied',
    'returned', 'escalated', 'withdrawn', 'commented', 'archived')),
  from_status text,
  to_status text,
  reason text,
  created_at timestamptz not null default now()
);
create index approval_actions_record on public.approval_actions (record_type, record_id, created_at);

-- ------------------------------------------------- communication & policy

create table public.announcements (
  id uuid primary key default gen_random_uuid(),
  ref text not null unique default ('D5-AN-' || lpad(nextval('public.ref_announcement')::text, 4, '0')),
  title text not null check (length(title) between 3 and 160),
  body text not null default '',
  scope text not null default 'district' check (scope in ('district', 'department')),
  department_key text references public.departments(key),
  audience_min_tier public.tier not null default 'probationary',
  status text not null default 'draft' check (status in ('draft', 'published', 'archived')),
  -- Public visibility is a separate, explicit approval.
  is_public boolean not null default false,
  public_approved_by uuid references public.profiles(id),
  public_approved_at timestamptz,
  priority text not null default 'normal' check (priority in ('normal', 'important', 'urgent')),
  pinned boolean not null default false,
  published_at timestamptz,
  author_id uuid references public.profiles(id),
  author_name text,
  is_demo boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (scope = 'district' or department_key is not null)
);

create table public.policies (
  id uuid primary key default gen_random_uuid(),
  ref text not null unique default ('D5-POL-' || lpad(nextval('public.ref_policy')::text, 3, '0')),
  title text not null,
  category text not null default 'sop',
  department_key text references public.departments(key),
  version text not null default '1.0',
  summary text,
  body text,
  source_url text,
  status text not null default 'draft' check (status in ('draft', 'approved', 'superseded', 'archived')),
  requires_acknowledgment boolean not null default false,
  effective_date date,
  approved_by uuid references public.profiles(id),
  approved_at timestamptz,
  is_demo boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.policy_acknowledgments (
  policy_id uuid not null references public.policies(id),
  profile_id uuid not null references public.profiles(id),
  policy_version text not null,
  acknowledged_at timestamptz not null default now(),
  primary key (policy_id, profile_id, policy_version)
);

create table public.notifications (
  id uuid primary key default gen_random_uuid(),
  profile_id uuid not null references public.profiles(id) on delete cascade,
  title text not null,
  body text,
  link text,
  category text not null default 'general',
  priority text not null default 'normal' check (priority in ('normal', 'high', 'critical')),
  department_key text,
  related_type text,
  related_id uuid,
  dedupe_key text,
  read_at timestamptz,
  created_at timestamptz not null default now()
);
create unique index notifications_dedupe on public.notifications (profile_id, dedupe_key) where dedupe_key is not null;
create index notifications_unread on public.notifications (profile_id, created_at desc) where read_at is null;

-- Append-only audit trail.
create table public.audit_log (
  id bigint generated always as identity primary key,
  actor_id uuid references public.profiles(id),
  actor_name text,
  action text not null,
  entity_type text not null,
  entity_id uuid,
  entity_ref text,
  department_key text,
  before_value jsonb,
  after_value jsonb,
  created_at timestamptz not null default now()
);

create or replace function public.audit_log_immutable()
returns trigger language plpgsql as $$
begin
  raise exception 'audit_log is append-only';
end;
$$;

create trigger audit_log_no_update before update or delete on public.audit_log
  for each row execute function public.audit_log_immutable();

-- updated_at maintenance
create or replace function public.touch_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

create trigger profiles_touch before update on public.profiles for each row execute function public.touch_updated_at();
create trigger memberships_touch before update on public.memberships for each row execute function public.touch_updated_at();
create trigger shift_logs_touch before update on public.shift_logs for each row execute function public.touch_updated_at();
create trigger announcements_touch before update on public.announcements for each row execute function public.touch_updated_at();
create trigger policies_touch before update on public.policies for each row execute function public.touch_updated_at();

-- New sign-ins get a profile. Discord metadata fills the display name.
create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  meta jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
begin
  insert into public.profiles (id, display_name, discord_id, discord_username, avatar_url)
  values (
    new.id,
    coalesce(meta->'custom_claims'->>'global_name', meta->>'full_name', meta->>'name', split_part(coalesce(new.email, 'member'), '@', 1)),
    coalesce(meta->>'provider_id', meta->>'sub'),
    meta->>'name',
    meta->>'avatar_url'
  )
  on conflict (id) do nothing;
  return new;
end;
$$;

create trigger on_auth_user_created after insert on auth.users
  for each row execute function public.handle_new_user();

-- ===== supabase/migrations/20261026000002_access.sql
-- Access helpers and row-level security.
-- Helpers are SECURITY DEFINER so policies can consult memberships without
-- recursing through memberships' own policies.

create or replace function public.me()
returns uuid language sql stable as $$ select auth.uid() $$;

create or replace function public.is_admin()
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((select is_admin from public.profiles where id = auth.uid()), false)
$$;

-- Highest tier the caller holds in a department through an ACTIVE membership.
create or replace function public.my_tier(dept text)
returns public.tier language sql stable security definer set search_path = public as $$
  select m.tier from public.memberships m
  where m.profile_id = auth.uid() and m.department_key = dept and m.status = 'active'
  order by public.tier_rank(m.tier) desc limit 1
$$;

create or replace function public.has_tier(dept text, min_tier public.tier)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(public.tier_rank(public.my_tier(dept)) >= public.tier_rank(min_tier), false)
$$;

create or replace function public.is_active_member()
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.memberships where profile_id = auth.uid() and status = 'active')
$$;

create or replace function public.is_member_of(dept text)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.memberships
                 where profile_id = auth.uid() and department_key = dept and status = 'active')
$$;

-- DPS oversight: an active membership in an oversight department.
create or replace function public.is_dps()
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.memberships m join public.departments d on d.key = m.department_key
                 where m.profile_id = auth.uid() and m.status = 'active' and d.kind = 'oversight')
$$;

-- Routine operational records: own department, or DPS.
create or replace function public.can_read_department(dept text)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_member_of(dept) or public.is_dps()
$$;

-- Supervisory read of a department's personal submissions.
create or replace function public.can_supervise(dept text)
returns boolean language sql stable security definer set search_path = public as $$
  select public.has_tier(dept, 'supervisor') or public.is_dps()
$$;

-- Confidential personnel records. Technical admin does NOT imply this.
create or replace function public.can_view_personnel(dept text)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.memberships m join public.departments d on d.key = m.department_key
    where m.profile_id = auth.uid() and m.status = 'active'
      and ((m.department_key = dept and (public.tier_rank(m.tier) >= public.tier_rank('department_head') or m.can_view_personnel))
        or (d.kind = 'oversight' and m.can_view_personnel))
  )
$$;

-- Roster managers: department heads of that department, DPS command, or technical admin.
create or replace function public.can_manage_roster(dept text)
returns boolean language sql stable security definer set search_path = public as $$
  select public.has_tier(dept, 'high_command') or public.is_dps() or public.is_admin()
$$;

-- ------------------------------------------------------------------ RLS

alter table public.departments enable row level security;
alter table public.ranks enable row level security;
alter table public.approval_routes enable row level security;
alter table public.app_settings enable row level security;
alter table public.profiles enable row level security;
alter table public.memberships enable row level security;
alter table public.personnel_records enable row level security;
alter table public.shift_logs enable row level security;
alter table public.approval_actions enable row level security;
alter table public.announcements enable row level security;
alter table public.policies enable row level security;
alter table public.policy_acknowledgments enable row level security;
alter table public.notifications enable row level security;
alter table public.audit_log enable row level security;

-- Configuration: readable by everyone (public site shows departments); written via functions only.
create policy departments_read on public.departments for select using (active or public.is_admin());
create policy ranks_read on public.ranks for select using (true);
create policy routes_read on public.approval_routes for select to authenticated using (true);
create policy settings_read on public.app_settings for select to authenticated using (true);

-- Profiles: yourself; people who share an active department with you see names only via the
-- roster functions. Contact identifiers (PSN/Discord) are visible to supervisors of a shared
-- department, DPS and admins.
create policy profiles_self on public.profiles for select using (id = auth.uid());
create policy profiles_supervised on public.profiles for select using (
  public.is_dps() or public.is_admin() or exists (
    select 1 from public.memberships m
    where m.profile_id = profiles.id and m.status in ('active', 'pending', 'suspended')
      and public.can_supervise(m.department_key)
  )
);

-- Memberships: general roster information is visible to any active member of either
-- department; your own memberships (including pending) are always visible.
create policy memberships_own on public.memberships for select using (profile_id = auth.uid());
create policy memberships_roster on public.memberships for select using (
  public.is_active_member() and status in ('active', 'suspended')
);
create policy memberships_managers on public.memberships for select using (public.can_manage_roster(department_key));

create policy personnel_read on public.personnel_records for select using (public.can_view_personnel(department_key));

-- Shift logs: the submitter, and supervisors of that department (or DPS).
create policy shift_logs_own on public.shift_logs for select using (profile_id = auth.uid());
create policy shift_logs_supervisors on public.shift_logs for select using (
  status <> 'draft' and public.can_supervise(department_key)
);

create policy approval_actions_read on public.approval_actions for select using (
  submitter_id = auth.uid() or (department_key is not null and public.can_supervise(department_key))
);

-- Announcements: published district items for any active member; department items for that
-- department; drafts for command of the scope. Public visitors see only publicly approved items.
create policy announcements_public on public.announcements for select to anon using (
  status = 'published' and is_public and public_approved_at is not null
);
create policy announcements_members on public.announcements for select to authenticated using (
  (status = 'published' and (
     (scope = 'district' and public.is_active_member() and (
        public.is_dps() or exists (select 1 from public.memberships m where m.profile_id = auth.uid()
          and m.status = 'active' and public.tier_rank(m.tier) >= public.tier_rank(announcements.audience_min_tier))))
     or (scope = 'department' and public.has_tier(department_key, audience_min_tier))
     or (scope = 'department' and public.is_dps())
     or (is_public and public_approved_at is not null)))
  or (status <> 'published' and (
     public.is_dps() or (scope = 'department' and public.has_tier(department_key, 'high_command'))))
);

create policy policies_read on public.policies for select to authenticated using (
  (status in ('approved', 'superseded') and public.is_active_member()
     and (department_key is null or public.can_read_department(department_key)))
  or public.is_dps()
  or (department_key is not null and public.has_tier(department_key, 'high_command'))
);

create policy policy_acks_own on public.policy_acknowledgments for select using (
  profile_id = auth.uid() or public.is_dps()
);

create policy notifications_own on public.notifications for select using (profile_id = auth.uid());

create policy audit_read on public.audit_log for select using (
  public.is_admin() or public.is_dps()
  or (department_key is not null and public.has_tier(department_key, 'department_head'))
);

-- No INSERT/UPDATE/DELETE policies exist: with RLS on, direct writes from the browser are refused.

grant usage on schema public to anon, authenticated;
grant select on all tables in schema public to anon, authenticated;
revoke insert, update, delete, truncate on all tables in schema public from anon, authenticated;

-- ===== supabase/migrations/20261026000003_workflows.sql
-- Workflow functions. Each one authenticates the caller, checks authority,
-- writes the record, the approval timeline, notifications and the audit log
-- in one transaction. Errors use stable codes the UI maps to messages:
--   D5401 not signed in, D5403 forbidden, D5404 not found,
--   D5409 conflict (already decided, overlap, duplicate), D5422 invalid input.

create or replace function public.d5_raise(code text, msg text)
returns void language plpgsql as $$
begin
  raise exception using errcode = code, message = msg;
end;
$$;

create or replace function public.require_user()
returns public.profiles language plpgsql stable security definer set search_path = public as $$
declare p public.profiles;
begin
  select * into p from public.profiles where id = auth.uid();
  if p.id is null then perform public.d5_raise('D5401', 'Sign in to continue.'); end if;
  return p;
end;
$$;

create or replace function public.write_audit(
  p_actor public.profiles, p_action text, p_entity_type text, p_entity_id uuid,
  p_entity_ref text, p_department text, p_before jsonb default null, p_after jsonb default null)
returns void language sql security definer set search_path = public as $$
  insert into public.audit_log (actor_id, actor_name, action, entity_type, entity_id, entity_ref, department_key, before_value, after_value)
  values (p_actor.id, p_actor.display_name, p_action, p_entity_type, p_entity_id, p_entity_ref, p_department, p_before, p_after)
$$;

create or replace function public.notify(
  p_profile uuid, p_title text, p_body text, p_link text, p_category text,
  p_priority text default 'normal', p_department text default null,
  p_related_type text default null, p_related_id uuid default null, p_dedupe text default null)
returns void language sql security definer set search_path = public as $$
  insert into public.notifications (profile_id, title, body, link, category, priority, department_key, related_type, related_id, dedupe_key)
  values (p_profile, p_title, p_body, p_link, p_category, p_priority, p_department, p_related_type, p_related_id, p_dedupe)
  on conflict (profile_id, dedupe_key) where dedupe_key is not null do nothing
$$;

create or replace function public.week_start_for(ts timestamptz, tz text, starts_on int)
returns date language sql immutable as $$
  select d - ((extract(dow from d)::int - starts_on + 7) % 7)
  from (select (ts at time zone tz)::date as d) x
$$;

create or replace function public.required_tier_for(p_record_type text, p_dept text, p_submitter public.tier)
returns public.tier language sql stable security definer set search_path = public as $$
  select coalesce(
    (select required_tier from public.approval_routes
      where record_type = p_record_type and department_key = p_dept and submitter_tier = p_submitter),
    (select required_tier from public.approval_routes
      where record_type = p_record_type and department_key is null and submitter_tier = p_submitter),
    case p_submitter
      when 'probationary' then 'supervisor'::public.tier
      when 'patrol' then 'supervisor'::public.tier
      when 'supervisor' then 'high_command'::public.tier
      when 'high_command' then 'department_head'::public.tier
      else 'dps'::public.tier
    end)
$$;

-- Can the caller decide a record in `dept` that needs `needed`?
-- Department reviewers need the tier in that department; DPS may review any department.
create or replace function public.can_decide(dept text, needed public.tier)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_dps()
      or (needed <> 'dps' and public.has_tier(dept, needed))
$$;

-- Reviewers to notify for a department and tier (excluding the submitter).
create or replace function public.reviewers_for(dept text, needed public.tier, exclude uuid)
returns setof uuid language sql stable security definer set search_path = public as $$
  select distinct m.profile_id from public.memberships m join public.departments d on d.key = m.department_key
  where m.status = 'active' and m.profile_id is not null and m.profile_id <> coalesce(exclude, '00000000-0000-0000-0000-000000000000')
    and ((m.department_key = dept and needed <> 'dps' and public.tier_rank(m.tier) >= public.tier_rank(needed))
      or (d.kind = 'oversight' and public.tier_rank(needed) >= public.tier_rank('department_head')))
$$;

-- ---------------------------------------------------------------- session

create or replace function public.set_active_department(p_department text)
returns text language plpgsql security definer set search_path = public as $$
declare p public.profiles := public.require_user();
begin
  if not public.is_member_of(p_department) then
    perform public.d5_raise('D5403', 'You do not hold an active membership in that department.');
  end if;
  update public.profiles set active_department = p_department where id = p.id;
  return p_department;
end;
$$;

create or replace function public.update_my_profile(p_display_name text, p_psn_id text)
returns void language plpgsql security definer set search_path = public as $$
declare p public.profiles := public.require_user();
begin
  if length(trim(coalesce(p_display_name, ''))) < 2 then perform public.d5_raise('D5422', 'Display name is too short.'); end if;
  update public.profiles set display_name = left(trim(p_display_name), 60), psn_id = nullif(left(trim(coalesce(p_psn_id, '')), 32), '')
  where id = p.id;
end;
$$;

create or replace function public.set_duty_status(p_department text, p_status public.duty_status)
returns public.duty_status language plpgsql security definer set search_path = public as $$
declare p public.profiles := public.require_user();
begin
  update public.memberships set duty_status = p_status, duty_changed_at = now()
  where profile_id = p.id and department_key = p_department and status = 'active';
  if not found then perform public.d5_raise('D5403', 'You do not hold an active membership in that department.'); end if;
  -- going on duty in one department takes you off duty in the others
  if p_status = 'on_duty' then
    update public.memberships set duty_status = 'off_duty', duty_changed_at = now()
    where profile_id = p.id and department_key <> p_department and duty_status = 'on_duty';
  end if;
  return p_status;
end;
$$;

create or replace function public.mark_notifications_read(p_id uuid default null)
returns void language plpgsql security definer set search_path = public as $$
declare p public.profiles := public.require_user();
begin
  update public.notifications set read_at = now()
  where profile_id = p.id and read_at is null and (p_id is null or id = p_id);
end;
$$;

-- ------------------------------------------------------------ memberships

-- A signed-in person asks to join a department. Command reviews it.
create or replace function public.request_membership(p_department text, p_note text default null)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  d public.departments;
  new_id uuid;
begin
  select * into d from public.departments where key = p_department and active;
  if d.key is null then perform public.d5_raise('D5404', 'Department not found.'); end if;
  if d.kind = 'oversight' then perform public.d5_raise('D5403', 'DPS memberships are assigned by DPS command.'); end if;
  if exists (select 1 from public.memberships where profile_id = p.id and department_key = p_department
             and status in ('pending', 'active', 'suspended')) then
    perform public.d5_raise('D5409', 'You already have a membership or request for this department.');
  end if;
  insert into public.memberships (profile_id, display_name, department_key, status, tier, is_probationary, request_note)
  values (p.id, p.display_name, p_department, 'pending', 'probationary', true, left(p_note, 600))
  returning id into new_id;
  insert into public.approval_actions (record_type, record_id, department_key, submitter_id, actor_id, actor_name, action, to_status, reason)
  values ('membership', new_id, p_department, p.id, p.id, p.display_name, 'submitted', 'pending', left(p_note, 600));
  perform public.notify(r, 'Roster request · ' || p.display_name, 'New ' || d.short_name || ' membership request.',
                        '/hub/roster?dept=' || p_department, 'roster', 'normal', p_department, 'membership', new_id, 'mbreq:' || new_id)
  from public.reviewers_for(p_department, 'high_command', p.id) r;
  perform public.write_audit(p, 'membership.requested', 'membership', new_id, null, p_department);
  return new_id;
end;
$$;

-- Approve or deny a pending membership, assigning rank, callsign and badge.
create or replace function public.decide_membership(
  p_membership uuid, p_action text, p_rank uuid default null, p_callsign text default null,
  p_badge text default null, p_reason text default null)
returns public.memberships language plpgsql security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  m public.memberships;
  r public.ranks;
begin
  select * into m from public.memberships where id = p_membership for update;
  if m.id is null then perform public.d5_raise('D5404', 'Membership not found.'); end if;
  if not public.can_manage_roster(m.department_key) then perform public.d5_raise('D5403', 'High command authority is required to decide roster requests.'); end if;
  if m.profile_id = p.id then perform public.d5_raise('D5403', 'You cannot approve your own roster request.'); end if;
  if m.status <> 'pending' then perform public.d5_raise('D5409', 'This request was already decided.'); end if;

  if p_action = 'approve' then
    select * into r from public.ranks where id = p_rank and department_key = m.department_key and active;
    if r.id is null then perform public.d5_raise('D5422', 'Choose a rank from this department''s ladder.'); end if;
    -- only DPS or admin may grant department_head or higher; nobody grants above their own tier
    if public.tier_rank(r.tier) >= public.tier_rank('department_head') and not (public.is_dps() or public.is_admin()) then
      perform public.d5_raise('D5403', 'Only DPS can appoint department heads.');
    end if;
    if not (public.is_dps() or public.is_admin()) and public.tier_rank(r.tier) >= public.tier_rank(public.my_tier(m.department_key)) then
      perform public.d5_raise('D5403', 'You cannot appoint someone at or above your own tier.');
    end if;
    update public.memberships set status = 'active', rank_id = r.id, rank_name = r.name, tier = r.tier,
      callsign = nullif(trim(p_callsign), ''), badge = nullif(trim(p_badge), ''),
      is_probationary = (r.tier = 'probationary'), join_date = coalesce(join_date, current_date)
    where id = m.id returning * into m;
    insert into public.personnel_records (membership_id, department_key, category, title, after_value, created_by, created_by_name)
    values (m.id, m.department_key, 'roster_change', 'Added to roster as ' || r.name,
            jsonb_build_object('rank', r.name, 'callsign', m.callsign, 'badge', m.badge), p.id, p.display_name);
  elsif p_action = 'deny' then
    if length(trim(coalesce(p_reason, ''))) < 5 then perform public.d5_raise('D5422', 'A denial needs a reason.'); end if;
    update public.memberships set status = 'denied' where id = m.id returning * into m;
  else
    perform public.d5_raise('D5422', 'Unknown action.');
  end if;

  insert into public.approval_actions (record_type, record_id, record_ref, department_key, submitter_id, actor_id, actor_name, actor_tier, action, from_status, to_status, reason)
  values ('membership', m.id, m.ref, m.department_key, m.profile_id, p.id, p.display_name, public.my_tier(m.department_key),
          case when p_action = 'approve' then 'approved' else 'denied' end, 'pending', m.status::text, p_reason);
  if m.profile_id is not null then
    perform public.notify(m.profile_id,
      case when p_action = 'approve' then 'Welcome to ' || upper(m.department_key) else 'Roster request denied' end,
      coalesce(p_reason, case when p_action = 'approve' then 'You are on the roster as ' || m.rank_name || '.' end),
      '/hub/roster/' || m.id, 'roster', 'high', m.department_key, 'membership', m.id, null);
  end if;
  perform public.write_audit(p, 'membership.' || p_action, 'membership', m.id, m.ref, m.department_key, null, to_jsonb(m));
  return m;
end;
$$;

-- Personnel change on an existing membership: rank, callsign, badge, status, leave, supervisor.
create or replace function public.update_membership(
  p_membership uuid, p_rank uuid default null, p_callsign text default null, p_badge text default null,
  p_status public.membership_status default null, p_leave_until date default null, p_clear_leave boolean default false,
  p_supervisor uuid default null, p_training_officer uuid default null, p_subdivisions text[] default null,
  p_can_view_personnel boolean default null, p_reason text default null)
returns public.memberships language plpgsql security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  m public.memberships;
  before_m public.memberships;
  r public.ranks;
  personnel_change boolean := false;
begin
  select * into m from public.memberships where id = p_membership for update;
  if m.id is null then perform public.d5_raise('D5404', 'Membership not found.'); end if;
  before_m := m;
  if not public.can_manage_roster(m.department_key) then perform public.d5_raise('D5403', 'High command authority is required to change the roster.'); end if;
  if m.profile_id = p.id and not public.is_admin() then perform public.d5_raise('D5403', 'Another commander must change your own membership.'); end if;
  if m.status in ('pending', 'denied') then perform public.d5_raise('D5409', 'Decide the roster request first.'); end if;
  if length(trim(coalesce(p_reason, ''))) < 3 then perform public.d5_raise('D5422', 'Give a short reason for the change.'); end if;

  if p_rank is not null and p_rank is distinct from m.rank_id then
    select * into r from public.ranks where id = p_rank and department_key = m.department_key and active;
    if r.id is null then perform public.d5_raise('D5422', 'Choose a rank from this department''s ladder.'); end if;
    if public.tier_rank(r.tier) >= public.tier_rank('department_head') and not (public.is_dps() or public.is_admin()) then
      perform public.d5_raise('D5403', 'Only DPS can appoint department heads.');
    end if;
    if not (public.is_dps() or public.is_admin()) and public.tier_rank(r.tier) >= public.tier_rank(public.my_tier(m.department_key)) then
      perform public.d5_raise('D5403', 'You cannot promote someone to or above your own tier.');
    end if;
    m.rank_id := r.id; m.rank_name := r.name; m.tier := r.tier; m.is_probationary := (r.tier = 'probationary');
    personnel_change := true;
  end if;
  if p_status is not null and p_status is distinct from m.status then
    if p_status not in ('active', 'suspended', 'removed') then perform public.d5_raise('D5422', 'Invalid status.'); end if;
    m.status := p_status;
    if p_status <> 'active' then m.duty_status := 'off_duty'; end if;
    personnel_change := true;
  end if;
  if p_can_view_personnel is not null and p_can_view_personnel is distinct from m.can_view_personnel then
    if not (public.is_dps() or public.has_tier(m.department_key, 'department_head')) then
      perform public.d5_raise('D5403', 'Only a department head or DPS can grant personnel-record access.');
    end if;
    m.can_view_personnel := p_can_view_personnel;
    personnel_change := true;
  end if;
  if p_callsign is not null then m.callsign := nullif(trim(p_callsign), ''); end if;
  if p_badge is not null then m.badge := nullif(trim(p_badge), ''); end if;
  if p_clear_leave then m.leave_until := null; elsif p_leave_until is not null then m.leave_until := p_leave_until; end if;
  if p_supervisor is not null then m.supervisor_id := p_supervisor; end if;
  if p_training_officer is not null then m.training_officer_id := p_training_officer; end if;
  if p_subdivisions is not null then m.subdivisions := p_subdivisions; end if;

  update public.memberships set rank_id = m.rank_id, rank_name = m.rank_name, tier = m.tier, is_probationary = m.is_probationary,
    status = m.status, duty_status = m.duty_status, can_view_personnel = m.can_view_personnel, callsign = m.callsign,
    badge = m.badge, leave_until = m.leave_until, supervisor_id = m.supervisor_id,
    training_officer_id = m.training_officer_id, subdivisions = m.subdivisions
  where id = m.id returning * into m;

  insert into public.personnel_records (membership_id, department_key, category, title, detail, before_value, after_value, created_by, created_by_name)
  values (m.id, m.department_key,
    case when before_m.tier is distinct from m.tier and public.tier_rank(m.tier) > public.tier_rank(before_m.tier) then 'promotion'
         when before_m.tier is distinct from m.tier then 'demotion'
         when before_m.rank_id is distinct from m.rank_id then 'rank_change'
         when before_m.status is distinct from m.status then 'status_change'
         when before_m.leave_until is distinct from m.leave_until then 'leave'
         else 'roster_change' end,
    coalesce(case when before_m.rank_id is distinct from m.rank_id then coalesce(before_m.rank_name, '—') || ' → ' || m.rank_name end,
             case when before_m.status is distinct from m.status then 'Status: ' || before_m.status || ' → ' || m.status end,
             'Roster details updated'),
    p_reason,
    jsonb_build_object('rank', before_m.rank_name, 'tier', before_m.tier, 'status', before_m.status, 'callsign', before_m.callsign, 'badge', before_m.badge, 'leave_until', before_m.leave_until),
    jsonb_build_object('rank', m.rank_name, 'tier', m.tier, 'status', m.status, 'callsign', m.callsign, 'badge', m.badge, 'leave_until', m.leave_until),
    p.id, p.display_name);

  if m.profile_id is not null and personnel_change then
    perform public.notify(m.profile_id, 'Your ' || upper(m.department_key) || ' membership changed',
      coalesce(m.rank_name, '') || ' · ' || m.status::text, '/hub/roster/' || m.id, 'roster', 'high', m.department_key, 'membership', m.id, null);
  end if;
  perform public.write_audit(p, 'membership.updated', 'membership', m.id, m.ref, m.department_key, to_jsonb(before_m), to_jsonb(m));
  return m;
end;
$$;

-- ------------------------------------------------------------- shift logs

create or replace function public.save_shift_log(
  p_id uuid, p_department text, p_started_at timestamptz, p_ended_at timestamptz,
  p_break_minutes int, p_activity_type text, p_summary text, p_cad_reference text,
  p_recording_url text, p_bodycam_status text, p_bodycam_explanation text,
  p_submit boolean, p_expected_version int default null)
returns public.shift_logs language plpgsql security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  m public.memberships;
  d public.departments;
  s public.shift_logs;
  dur int;
  clash public.shift_logs;
  was_status public.approval_status;
begin
  select * into m from public.memberships
   where profile_id = p.id and department_key = p_department and status = 'active';
  if m.id is null then perform public.d5_raise('D5403', 'You do not hold an active membership in ' || upper(p_department) || '.'); end if;
  select * into d from public.departments where key = p_department;

  dur := floor(extract(epoch from (p_ended_at - p_started_at)) / 60)::int - coalesce(p_break_minutes, 0);
  if p_ended_at <= p_started_at then perform public.d5_raise('D5422', 'End time must be after the start time.'); end if;
  if dur < 5 then perform public.d5_raise('D5422', 'A shift must include at least 5 minutes of activity.'); end if;
  if dur > 960 then perform public.d5_raise('D5422', 'A single entry cannot exceed 16 hours. Split it into separate shifts.'); end if;
  if p_started_at > now() + interval '15 minutes' then perform public.d5_raise('D5422', 'Shifts cannot start in the future.'); end if;
  if p_submit and d.bodycam_required and coalesce(p_bodycam_status, 'not_required') not in ('recorded', 'unavailable', 'not_applicable') then
    perform public.d5_raise('D5422', upper(p_department) || ' requires a bodycam status on every submitted shift.');
  end if;
  if p_bodycam_status = 'recorded' and coalesce(p_recording_url, '') !~* '^https?://' then
    perform public.d5_raise('D5422', 'Add the recording link, or choose another bodycam status.');
  end if;
  if p_bodycam_status = 'unavailable' and length(trim(coalesce(p_bodycam_explanation, ''))) < 10 then
    perform public.d5_raise('D5422', 'Explain briefly why footage is unavailable.');
  end if;

  select * into clash from public.shift_logs
   where profile_id = p.id and id is distinct from p_id and status not in ('withdrawn', 'denied', 'archived')
     and tstzrange(started_at, ended_at, '[)') && tstzrange(p_started_at, p_ended_at, '[)')
   limit 1;
  if clash.id is not null then
    perform public.d5_raise('D5409', 'These hours overlap ' || clash.ref || ' (' || upper(clash.department_key) || '). Time is never counted twice; adjust one entry.');
  end if;

  if p_id is null then
    insert into public.shift_logs (profile_id, membership_id, department_key, snapshot_name, snapshot_rank, snapshot_tier,
      snapshot_callsign, snapshot_badge, started_at, ended_at, break_minutes, duration_minutes, week_start, activity_type,
      summary, cad_reference, recording_url, bodycam_status, bodycam_explanation, status, required_tier, submitted_at)
    values (p.id, m.id, m.department_key, m.display_name, m.rank_name, m.tier, m.callsign, m.badge,
      p_started_at, p_ended_at, coalesce(p_break_minutes, 0), dur, public.week_start_for(p_started_at, d.timezone, d.week_starts_on),
      p_activity_type, coalesce(p_summary, ''), nullif(trim(coalesce(p_cad_reference, '')), ''), nullif(trim(coalesce(p_recording_url, '')), ''),
      coalesce(p_bodycam_status, 'not_required'), nullif(trim(coalesce(p_bodycam_explanation, '')), ''),
      (case when p_submit then 'submitted' else 'draft' end)::public.approval_status,
      public.required_tier_for('shift_log', m.department_key, m.tier),
      case when p_submit then now() end)
    returning * into s;
    was_status := null;
  else
    select * into s from public.shift_logs where id = p_id for update;
    if s.id is null then perform public.d5_raise('D5404', 'Shift log not found.'); end if;
    if s.profile_id <> p.id then perform public.d5_raise('D5403', 'You can only edit your own shift logs.'); end if;
    if s.status not in ('draft', 'returned', 'submitted') then perform public.d5_raise('D5409', 'This shift log was already decided and can no longer be edited.'); end if;
    if p_expected_version is not null and p_expected_version <> s.version then
      perform public.d5_raise('D5409', 'This entry changed in another window. Reload to see the latest version.');
    end if;
    if s.department_key <> p_department then perform public.d5_raise('D5422', 'Department cannot change after creation. Withdraw and create a new entry.'); end if;
    was_status := s.status;
    update public.shift_logs set
      snapshot_name = m.display_name, snapshot_rank = m.rank_name, snapshot_tier = m.tier,
      snapshot_callsign = m.callsign, snapshot_badge = m.badge,
      started_at = p_started_at, ended_at = p_ended_at, break_minutes = coalesce(p_break_minutes, 0), duration_minutes = dur,
      week_start = public.week_start_for(p_started_at, d.timezone, d.week_starts_on), activity_type = p_activity_type,
      summary = coalesce(p_summary, ''), cad_reference = nullif(trim(coalesce(p_cad_reference, '')), ''),
      recording_url = nullif(trim(coalesce(p_recording_url, '')), ''), bodycam_status = coalesce(p_bodycam_status, 'not_required'),
      bodycam_explanation = nullif(trim(coalesce(p_bodycam_explanation, '')), ''),
      status = case when p_submit then 'submitted'::public.approval_status else s.status end,
      submitted_at = case when p_submit then now() else s.submitted_at end,
      required_tier = public.required_tier_for('shift_log', m.department_key, m.tier),
      decision_reason = case when p_submit and s.status = 'returned' then null else s.decision_reason end,
      version = s.version + 1
    where id = s.id returning * into s;
  end if;

  if p_submit and (was_status is null or was_status in ('draft', 'returned')) then
    insert into public.approval_actions (record_type, record_id, record_ref, department_key, submitter_id, actor_id, actor_name, actor_tier, action, from_status, to_status)
    values ('shift_log', s.id, s.ref, s.department_key, p.id, p.id, p.display_name, m.tier,
            case when was_status = 'returned' then 'resubmitted' else 'submitted' end, was_status::text, 'submitted');
    perform public.notify(r, 'Shift log to review · ' || s.snapshot_name,
      s.ref || ' · ' || round(s.duration_minutes / 60.0, 1) || 'h ' || s.activity_type,
      '/hub/shifts/' || s.id, 'approval', 'normal', s.department_key, 'shift_log', s.id, 'shiftsub:' || s.id || ':' || s.version)
    from public.reviewers_for(s.department_key, s.required_tier, p.id) r;
  end if;
  perform public.write_audit(p, case when p_submit then 'shift.submitted' else 'shift.saved' end, 'shift_log', s.id, s.ref, s.department_key);
  return s;
exception
  when exclusion_violation then
    perform public.d5_raise('D5409', 'These hours overlap another of your entries. Time is never counted twice; adjust one entry.');
end;
$$;

create or replace function public.withdraw_shift_log(p_id uuid, p_reason text default null)
returns public.shift_logs language plpgsql security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  s public.shift_logs;
  was public.approval_status;
begin
  select * into s from public.shift_logs where id = p_id for update;
  if s.id is null then perform public.d5_raise('D5404', 'Shift log not found.'); end if;
  if s.profile_id <> p.id then perform public.d5_raise('D5403', 'You can only withdraw your own shift logs.'); end if;
  if s.status not in ('draft', 'submitted', 'under_review', 'returned') then
    perform public.d5_raise('D5409', 'A decided shift log cannot be withdrawn.');
  end if;
  was := s.status;
  update public.shift_logs set status = 'withdrawn', decision_reason = nullif(trim(coalesce(p_reason, '')), ''), version = version + 1
  where id = s.id returning * into s;
  insert into public.approval_actions (record_type, record_id, record_ref, department_key, submitter_id, actor_id, actor_name, action, from_status, to_status, reason)
  values ('shift_log', s.id, s.ref, s.department_key, p.id, p.id, p.display_name, 'withdrawn', was::text, 'withdrawn', p_reason);
  perform public.write_audit(p, 'shift.withdrawn', 'shift_log', s.id, s.ref, s.department_key);
  return s;
end;
$$;

-- The single decision point for shift logs: approve, deny, return, escalate, claim.
create or replace function public.decide_shift_log(p_id uuid, p_action text, p_reason text default null)
returns public.shift_logs language plpgsql security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  s public.shift_logs;
  was public.approval_status;
  reviewer_tier public.tier;
begin
  -- row lock serializes concurrent reviewers; the loser sees the new status below
  select * into s from public.shift_logs where id = p_id for update;
  if s.id is null then perform public.d5_raise('D5404', 'Shift log not found.'); end if;
  if s.profile_id = p.id then perform public.d5_raise('D5403', 'You cannot review your own submission. Another reviewer must decide it.'); end if;
  if not public.can_decide(s.department_key, s.required_tier) then
    perform public.d5_raise('D5403', 'This needs a ' || replace(s.required_tier::text, '_', ' ') || ' or above in ' || upper(s.department_key) || ', or DPS.');
  end if;
  if s.status not in ('submitted', 'under_review') then
    perform public.d5_raise('D5409', 'This shift log was already ' || s.status || ' by ' || coalesce(s.decided_by_name, 'another reviewer') || '.');
  end if;
  if p_action in ('deny', 'return') and length(trim(coalesce(p_reason, ''))) < 5 then
    perform public.d5_raise('D5422', case when p_action = 'deny' then 'A denial needs a reason the member can act on.' else 'Say what needs correcting.' end);
  end if;

  was := s.status;
  reviewer_tier := coalesce(public.my_tier(s.department_key), case when public.is_dps() then 'dps'::public.tier end);
  if p_action = 'approve' then
    update public.shift_logs set status = 'approved', decided_at = now(), decided_by = p.id, decided_by_name = p.display_name,
      decision_reason = nullif(trim(coalesce(p_reason, '')), ''), version = version + 1 where id = s.id returning * into s;
  elsif p_action = 'deny' then
    update public.shift_logs set status = 'denied', decided_at = now(), decided_by = p.id, decided_by_name = p.display_name,
      decision_reason = p_reason, version = version + 1 where id = s.id returning * into s;
  elsif p_action = 'return' then
    update public.shift_logs set status = 'returned', decided_at = now(), decided_by = p.id, decided_by_name = p.display_name,
      decision_reason = p_reason, version = version + 1 where id = s.id returning * into s;
  elsif p_action = 'escalate' then
    if s.required_tier = 'dps' then perform public.d5_raise('D5409', 'This is already with DPS.'); end if;
    update public.shift_logs set status = 'under_review', required_tier = 'dps', assigned_to = null,
      decision_reason = nullif(trim(coalesce(p_reason, '')), ''), version = version + 1 where id = s.id returning * into s;
  elsif p_action = 'claim' then
    update public.shift_logs set status = 'under_review', assigned_to = p.id, version = version + 1 where id = s.id returning * into s;
  else
    perform public.d5_raise('D5422', 'Unknown action.');
  end if;

  insert into public.approval_actions (record_type, record_id, record_ref, department_key, submitter_id, actor_id, actor_name, actor_tier, action, from_status, to_status, reason)
  values ('shift_log', s.id, s.ref, s.department_key, s.profile_id, p.id, p.display_name, reviewer_tier,
          case p_action when 'approve' then 'approved' when 'deny' then 'denied' when 'return' then 'returned'
                        when 'escalate' then 'escalated' else 'claimed' end,
          was::text, s.status::text, p_reason);

  if p_action in ('approve', 'deny', 'return') then
    perform public.notify(s.profile_id,
      'Shift log ' || case p_action when 'approve' then 'approved' when 'deny' then 'denied' else 'returned for correction' end || ' · ' || s.ref,
      coalesce(p_reason, round(s.duration_minutes / 60.0, 1) || 'h counted toward this week.'),
      '/hub/shifts/' || s.id, 'approval', case when p_action = 'approve' then 'normal' else 'high' end,
      s.department_key, 'shift_log', s.id, null);
  elsif p_action = 'escalate' then
    perform public.notify(r, 'Escalated to DPS · ' || s.ref, coalesce(p_reason, s.snapshot_name), '/hub/shifts/' || s.id,
      'approval', 'high', s.department_key, 'shift_log', s.id, 'shiftesc:' || s.id)
    from public.reviewers_for(s.department_key, 'dps', s.profile_id) r;
  end if;
  perform public.write_audit(p, 'shift.' || p_action, 'shift_log', s.id, s.ref, s.department_key,
    jsonb_build_object('status', was), jsonb_build_object('status', s.status, 'reason', p_reason));
  return s;
end;
$$;

-- Weekly activity for the caller. Approved and pending minutes are reported separately.
-- Overlap is impossible by constraint, so summing never double counts across departments.
-- Mode 'combined' (default) measures one district quota; 'per_department' measures each.
create or replace function public.my_activity(p_weeks int default 6)
returns table (week_start date, department_key text, approved_minutes int, pending_minutes int,
               returned_count int, quota_minutes int, exempt boolean)
language plpgsql stable security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  primary_dept public.departments;
  this_week date;
begin
  select d.* into primary_dept from public.departments d
   where d.key = coalesce(p.active_department, (select m.department_key from public.memberships m where m.profile_id = p.id and m.status = 'active' order by m.join_date nulls last limit 1));
  this_week := public.week_start_for(now(), coalesce(primary_dept.timezone, 'America/New_York'), coalesce(primary_dept.week_starts_on, 1));
  return query
  with weeks as (
    select (this_week - (7 * g))::date as ws from generate_series(0, greatest(p_weeks, 1) - 1) g
  ), depts as (
    select m.department_key, m.leave_until, d.quota_minutes from public.memberships m join public.departments d on d.key = m.department_key
    where m.profile_id = p.id and m.status = 'active' and d.kind = 'department'
  )
  select w.ws, dp.department_key,
    coalesce(sum(s.duration_minutes) filter (where s.status = 'approved'), 0)::int,
    coalesce(sum(s.duration_minutes) filter (where s.status in ('submitted', 'under_review')), 0)::int,
    count(s.id) filter (where s.status = 'returned')::int,
    dp.quota_minutes,
    (dp.leave_until is not null and dp.leave_until >= w.ws)
  from weeks w cross join depts dp
  left join public.shift_logs s on s.profile_id = p.id and s.department_key = dp.department_key and s.week_start = w.ws
  group by w.ws, dp.department_key, dp.quota_minutes, dp.leave_until
  order by w.ws desc, dp.department_key;
end;
$$;

-- Department compliance for supervisors: members below quota this week (flag only; never a strike).
create or replace function public.department_compliance(p_department text)
returns table (membership_id uuid, display_name text, callsign text, rank_name text, tier public.tier,
               approved_minutes int, pending_minutes int, district_minutes int, quota_minutes int, on_leave boolean)
language plpgsql stable security definer set search_path = public as $$
declare
  d public.departments;
  ws date;
  mode text;
begin
  perform public.require_user();
  if not public.can_supervise(p_department) then perform public.d5_raise('D5403', 'Supervisor authority is required.'); end if;
  select * into d from public.departments where key = p_department;
  ws := public.week_start_for(now(), d.timezone, d.week_starts_on);
  select coalesce(value #>> '{}', 'combined') into mode from public.app_settings where key = 'dual_membership_mode';
  return query
  select m.id, m.display_name, m.callsign, m.rank_name, m.tier,
    coalesce(sum(s.duration_minutes) filter (where s.status = 'approved' and s.department_key = p_department), 0)::int,
    coalesce(sum(s.duration_minutes) filter (where s.status in ('submitted', 'under_review') and s.department_key = p_department), 0)::int,
    coalesce(sum(s.duration_minutes) filter (where s.status = 'approved'), 0)::int,
    d.quota_minutes,
    (m.leave_until is not null and m.leave_until >= ws)
  from public.memberships m
  left join public.shift_logs s on s.profile_id = m.profile_id and s.week_start = ws
  where m.department_key = p_department and m.status = 'active'
  group by m.id, m.display_name, m.callsign, m.rank_name, m.tier, m.leave_until
  order by 6 asc;
end;
$$;

-- ---------------------------------------------------- announcements/policy

create or replace function public.save_announcement(
  p_id uuid, p_title text, p_body text, p_scope text, p_department text, p_priority text,
  p_audience_min_tier public.tier, p_pinned boolean, p_publish boolean)
returns public.announcements language plpgsql security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  a public.announcements;
begin
  if p_id is not null then
    select * into a from public.announcements where id = p_id for update;
    if a.id is null then perform public.d5_raise('D5404', 'Announcement not found.'); end if;
    -- authority comes from the stored record; scope cannot change after creation
    p_scope := a.scope; p_department := a.department_key;
  end if;
  if p_scope not in ('district', 'department') then perform public.d5_raise('D5422', 'Unknown scope.'); end if;
  if p_scope = 'district' and not public.is_dps() then perform public.d5_raise('D5403', 'District announcements are published by DPS.'); end if;
  if p_scope = 'department' and not (public.has_tier(p_department, 'high_command') or public.is_dps()) then
    perform public.d5_raise('D5403', 'High command authority is required to publish department announcements.');
  end if;
  if p_id is null then
    insert into public.announcements (title, body, scope, department_key, priority, audience_min_tier, pinned, status, published_at, author_id, author_name)
    values (p_title, coalesce(p_body, ''), p_scope, case when p_scope = 'department' then p_department end, coalesce(p_priority, 'normal'),
            coalesce(p_audience_min_tier, 'probationary'), coalesce(p_pinned, false),
            case when p_publish then 'published' else 'draft' end, case when p_publish then now() end, p.id, p.display_name)
    returning * into a;
  else
    update public.announcements set title = p_title, body = coalesce(p_body, ''), priority = coalesce(p_priority, priority),
      audience_min_tier = coalesce(p_audience_min_tier, audience_min_tier), pinned = coalesce(p_pinned, pinned),
      status = case when p_publish then 'published' else status end,
      published_at = case when p_publish and published_at is null then now() else published_at end
    where id = a.id returning * into a;
  end if;
  perform public.write_audit(p, case when p_publish then 'announcement.published' else 'announcement.saved' end, 'announcement', a.id, a.ref, a.department_key);
  return a;
end;
$$;

-- Separate approval to show a published announcement on the public site.
create or replace function public.set_announcement_public(p_id uuid, p_public boolean)
returns public.announcements language plpgsql security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  a public.announcements;
begin
  select * into a from public.announcements where id = p_id for update;
  if a.id is null then perform public.d5_raise('D5404', 'Announcement not found.'); end if;
  if not (public.is_dps() or (a.scope = 'department' and public.has_tier(a.department_key, 'department_head'))) then
    perform public.d5_raise('D5403', 'A department head or DPS must approve public content.');
  end if;
  if p_public and a.status <> 'published' then perform public.d5_raise('D5409', 'Publish it internally before approving it for the public site.'); end if;
  update public.announcements set is_public = p_public,
    public_approved_by = case when p_public then p.id end, public_approved_at = case when p_public then now() end
  where id = a.id returning * into a;
  perform public.write_audit(p, case when p_public then 'announcement.public_approved' else 'announcement.public_removed' end, 'announcement', a.id, a.ref, a.department_key);
  return a;
end;
$$;

create or replace function public.acknowledge_policy(p_policy uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  pol public.policies;
begin
  select * into pol from public.policies where id = p_policy and status = 'approved';
  if pol.id is null then perform public.d5_raise('D5404', 'Policy not found.'); end if;
  if not public.is_active_member() then perform public.d5_raise('D5403', 'Active membership required.'); end if;
  insert into public.policy_acknowledgments (policy_id, profile_id, policy_version) values (pol.id, p.id, pol.version)
  on conflict do nothing;
end;
$$;

create or replace function public.save_policy(
  p_id uuid, p_title text, p_category text, p_department text, p_version text, p_summary text,
  p_body text, p_source_url text, p_requires_ack boolean, p_effective date, p_approve boolean)
returns public.policies language plpgsql security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  pol public.policies;
begin
  if p_id is not null then
    select * into pol from public.policies where id = p_id for update;
    if pol.id is null then perform public.d5_raise('D5404', 'Policy not found.'); end if;
    p_department := pol.department_key;
  end if;
  if p_department is null and not public.is_dps() then perform public.d5_raise('D5403', 'District policies are managed by DPS.'); end if;
  if p_department is not null and not (public.has_tier(p_department, 'department_head') or public.is_dps()) then
    perform public.d5_raise('D5403', 'A department head or DPS manages department policies.');
  end if;
  if p_id is null then
    insert into public.policies (title, category, department_key, version, summary, body, source_url, requires_acknowledgment, effective_date, status, approved_by, approved_at)
    values (p_title, coalesce(p_category, 'sop'), p_department, coalesce(p_version, '1.0'), p_summary, p_body, p_source_url, coalesce(p_requires_ack, false), p_effective,
            case when p_approve then 'approved' else 'draft' end, case when p_approve then p.id end, case when p_approve then now() end)
    returning * into pol;
  else
    update public.policies set title = p_title, category = coalesce(p_category, category), version = coalesce(p_version, version),
      summary = p_summary, body = p_body, source_url = p_source_url, requires_acknowledgment = coalesce(p_requires_ack, requires_acknowledgment),
      effective_date = p_effective, status = case when p_approve then 'approved' else status end,
      approved_by = case when p_approve then p.id else approved_by end, approved_at = case when p_approve then now() else approved_at end
    where id = pol.id returning * into pol;
  end if;
  perform public.write_audit(p, 'policy.saved', 'policy', pol.id, pol.ref, pol.department_key);
  return pol;
end;
$$;

-- --------------------------------------------------------- administration

create or replace function public.admin_update_department(
  p_key text, p_quota_minutes int, p_week_starts_on int, p_timezone text,
  p_bodycam_required boolean, p_bodycam_policy_text text, p_bodycam_policy_url text)
returns public.departments language plpgsql security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  before_d public.departments;
  d public.departments;
begin
  if not public.is_admin() then perform public.d5_raise('D5403', 'Administrator access is required.'); end if;
  select * into before_d from public.departments where key = p_key for update;
  if before_d.key is null then perform public.d5_raise('D5404', 'Department not found.'); end if;
  if p_timezone is not null and not exists (select 1 from pg_timezone_names where name = p_timezone) then
    perform public.d5_raise('D5422', 'Unknown time zone.');
  end if;
  update public.departments set quota_minutes = coalesce(p_quota_minutes, quota_minutes), week_starts_on = coalesce(p_week_starts_on, week_starts_on),
    timezone = coalesce(p_timezone, timezone), bodycam_required = coalesce(p_bodycam_required, bodycam_required),
    bodycam_policy_text = p_bodycam_policy_text, bodycam_policy_url = p_bodycam_policy_url
  where key = p_key returning * into d;
  perform public.write_audit(p, 'department.updated', 'department', null, d.key, d.key, to_jsonb(before_d), to_jsonb(d));
  return d;
end;
$$;

create or replace function public.admin_save_rank(
  p_id uuid, p_department text, p_name text, p_abbreviation text, p_tier public.tier, p_sort int, p_active boolean)
returns public.ranks language plpgsql security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  r public.ranks;
begin
  if not public.is_admin() then perform public.d5_raise('D5403', 'Administrator access is required.'); end if;
  if p_id is null then
    insert into public.ranks (department_key, name, abbreviation, tier, sort_order, is_sample, active)
    values (p_department, p_name, p_abbreviation, p_tier, coalesce(p_sort, 0), false, coalesce(p_active, true)) returning * into r;
  else
    update public.ranks set name = p_name, abbreviation = p_abbreviation, tier = p_tier, sort_order = coalesce(p_sort, sort_order),
      active = coalesce(p_active, active), is_sample = false where id = p_id returning * into r;
    if r.id is null then perform public.d5_raise('D5404', 'Rank not found.'); end if;
  end if;
  perform public.write_audit(p, 'rank.saved', 'rank', r.id, r.name, r.department_key, null, to_jsonb(r));
  return r;
end;
$$;

-- Roster seeding for an administrator: create a membership not yet linked to an account.
-- It links itself when that person signs in with the matching Discord ID.
create or replace function public.admin_add_roster_member(
  p_department text, p_display_name text, p_discord_id text, p_rank uuid, p_callsign text, p_badge text, p_join_date date)
returns public.memberships language plpgsql security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  r public.ranks;
  m public.memberships;
  linked uuid;
begin
  if not public.can_manage_roster(p_department) then perform public.d5_raise('D5403', 'High command authority is required.'); end if;
  select * into r from public.ranks where id = p_rank and department_key = p_department;
  if r.id is null then perform public.d5_raise('D5422', 'Choose a rank from this department''s ladder.'); end if;
  if public.tier_rank(r.tier) >= public.tier_rank('department_head') and not (public.is_dps() or public.is_admin()) then
    perform public.d5_raise('D5403', 'Only DPS can appoint department heads.');
  end if;
  select id into linked from public.profiles where discord_id = nullif(trim(p_discord_id), '');
  insert into public.memberships (profile_id, display_name, department_key, rank_id, rank_name, tier, callsign, badge, status, is_probationary, join_date, request_note)
  values (linked, p_display_name, p_department, r.id, r.name, r.tier, nullif(trim(p_callsign), ''), nullif(trim(p_badge), ''), 'active',
          r.tier = 'probationary', coalesce(p_join_date, current_date), case when linked is null then 'discord:' || nullif(trim(p_discord_id), '') end)
  returning * into m;
  perform public.write_audit(p, 'membership.added', 'membership', m.id, m.ref, m.department_key, null, to_jsonb(m));
  return m;
end;
$$;

-- Link roster rows imported by Discord ID to the account that just signed in.
create or replace function public.link_roster_on_signin()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.discord_id is not null then
    update public.memberships set profile_id = new.id
    where profile_id is null and request_note = 'discord:' || new.discord_id;
  end if;
  return new;
end;
$$;

create trigger profiles_link_roster after insert on public.profiles
  for each row execute function public.link_roster_on_signin();

-- Functions are the write path. Lock them to signed-in callers.
revoke execute on all functions in schema public from public, anon;
grant execute on all functions in schema public to authenticated;
-- policy helpers must stay callable by anon so anonymous policy checks evaluate
grant execute on function public.tier_rank(public.tier), public.is_admin(), public.my_tier(text), public.has_tier(text, public.tier),
  public.is_active_member(), public.is_member_of(text), public.is_dps(), public.can_read_department(text),
  public.can_supervise(text), public.can_view_personnel(text), public.can_manage_roster(text), public.me() to anon;
-- internal helpers are not part of the API
revoke execute on function public.write_audit(public.profiles, text, text, uuid, text, text, jsonb, jsonb),
  public.notify(uuid, text, text, text, text, text, text, text, uuid, text),
  public.d5_raise(text, text), public.handle_new_user(), public.link_roster_on_signin(),
  public.audit_log_immutable(), public.touch_updated_at() from authenticated;

-- ===== supabase/migrations/20261026000004_admin.sql
-- Administration: settings, approval routing, and labeled demo data.

create or replace function public.admin_set_setting(p_key text, p_value jsonb)
returns void language plpgsql security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  before_v jsonb;
begin
  if not public.is_admin() then perform public.d5_raise('D5403', 'Administrator access is required.'); end if;
  if p_key = 'dual_membership_mode' and p_value #>> '{}' not in ('combined', 'per_department') then
    perform public.d5_raise('D5422', 'Choose combined or per_department.');
  end if;
  select value into before_v from public.app_settings where key = p_key;
  insert into public.app_settings (key, value, updated_at) values (p_key, p_value, now())
  on conflict (key) do update set value = excluded.value, updated_at = now();
  perform public.write_audit(p, 'setting.updated', 'setting', null, p_key, null, before_v, p_value);
end;
$$;

create or replace function public.admin_save_route(
  p_record_type text, p_department text, p_submitter public.tier, p_required public.tier)
returns void language plpgsql security definer set search_path = public as $$
declare p public.profiles := public.require_user();
begin
  if not public.is_admin() then perform public.d5_raise('D5403', 'Administrator access is required.'); end if;
  if public.tier_rank(p_required) <= public.tier_rank(p_submitter) and p_required <> 'dps' then
    perform public.d5_raise('D5422', 'Reviewers must hold a higher tier than the submitter.');
  end if;
  insert into public.approval_routes (record_type, department_key, submitter_tier, required_tier)
  values (p_record_type, p_department, p_submitter, p_required)
  on conflict (record_type, department_key, submitter_tier) do update set required_tier = excluded.required_tier;
  perform public.write_audit(p, 'route.saved', 'approval_route', null, p_record_type, p_department, null,
    jsonb_build_object('submitter', p_submitter, 'required', p_required));
end;
$$;

-- Fictional sample content so a fresh hub is not empty. Every row is is_demo and
-- prefixed [DEMO]; admin_clear_demo removes all of it.
create or replace function public.admin_seed_demo()
returns int language plpgsql security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  n int := 0;
  rec record;
begin
  if not public.is_admin() then perform public.d5_raise('D5403', 'Administrator access is required.'); end if;
  if exists (select 1 from public.memberships where is_demo) then perform public.d5_raise('D5409', 'Demo data is already loaded.'); end if;
  for rec in
    select * from (values
      ('bcso', '[DEMO] R. Calloway', 'Sergeant', '1S-12', 'on_duty'),
      ('bcso', '[DEMO] T. Marsh', 'Deputy Sheriff First Class', '1D-31', 'off_duty'),
      ('bcso', '[DEMO] L. Ortega', 'Deputy Sheriff Third Class', '1D-48', 'off_duty'),
      ('sahp', '[DEMO] K. Whitfield', 'Lieutenant', '3A-04', 'off_duty'),
      ('sahp', '[DEMO] D. Reyes', 'Senior Trooper', '4A-22', 'on_duty'),
      ('sahp', '[DEMO] J. Park', 'Probationary Trooper', '5A-61', 'off_duty')
    ) v(dept, name, rank, callsign, duty)
  loop
    insert into public.memberships (display_name, department_key, rank_id, rank_name, tier, callsign, status, is_probationary,
                                    join_date, duty_status, is_demo)
    select rec.name, rec.dept, r.id, r.name, r.tier, rec.callsign, 'active', r.tier = 'probationary', current_date - 40,
           rec.duty::public.duty_status, true
    from public.ranks r where r.department_key = rec.dept and r.name = rec.rank;
    n := n + 1;
  end loop;
  insert into public.announcements (title, body, scope, status, published_at, author_name, is_demo, priority, pinned)
  values ('[DEMO] Welcome to the District Five hub',
          'This is sample content. Log shifts from the Shifts page, and supervisors review them under Approvals. An administrator can remove all demo content from Admin.',
          'district', 'published', now(), 'District Five', true, 'normal', true);
  perform public.write_audit(p, 'demo.seeded', 'demo', null, null, null, null, jsonb_build_object('members', n));
  return n;
end;
$$;

create or replace function public.admin_clear_demo()
returns int language plpgsql security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  n int;
begin
  if not public.is_admin() then perform public.d5_raise('D5403', 'Administrator access is required.'); end if;
  delete from public.personnel_records where membership_id in (select id from public.memberships where is_demo);
  update public.memberships set supervisor_id = null where supervisor_id in (select id from public.memberships where is_demo);
  update public.memberships set training_officer_id = null where training_officer_id in (select id from public.memberships where is_demo);
  delete from public.memberships where is_demo;
  get diagnostics n = row_count;
  delete from public.announcements where is_demo;
  delete from public.policies where is_demo and not exists (select 1 from public.policy_acknowledgments a where a.policy_id = policies.id);
  perform public.write_audit(p, 'demo.cleared', 'demo', null, null, null, null, jsonb_build_object('members', n));
  return n;
end;
$$;

revoke execute on function public.admin_set_setting(text, jsonb), public.admin_save_route(text, text, public.tier, public.tier),
  public.admin_seed_demo(), public.admin_clear_demo() from public, anon;
grant execute on function public.admin_set_setting(text, jsonb), public.admin_save_route(text, text, public.tier, public.tier),
  public.admin_seed_demo(), public.admin_clear_demo() to authenticated;

-- ===== supabase/migrations/20261027000005_divisions.sql
-- Divisions: District Five now covers law enforcement, Fire/EMS and (later) Dispatch.
-- Each department belongs to a division. An oversight department (DPS, Fire/EMS
-- Administration) oversees only the divisions listed in its `oversees` column, so one
-- division's command cannot read or decide another division's records.

alter table public.departments
  add column division text not null default 'leo' check (division in ('leo', 'fire_ems', 'dispatch')),
  add column oversees text[] not null default '{}';

update public.departments set oversees = '{leo}' where key = 'dps';

insert into public.departments (key, name, short_name, kind, division, oversees, tagline, accent, sort_order, bodycam_required) values
  ('safd', 'San Andreas Fire Department', 'SAFD', 'department', 'fire_ems', '{}', 'Fire and rescue', '#c8553d', 3, false),
  ('saems', 'San Andreas Emergency Medical Services', 'SAEMS', 'department', 'fire_ems', '{}', 'Emergency medical care', '#6fa8c9', 4, false),
  ('fems', 'Fire/EMS Administration', 'Fire/EMS Admin', 'oversight', 'fire_ems', '{fire_ems}', 'SAFD and SAEMS command', '#d8dde6', 0, false)
on conflict (key) do nothing;

-- Fire/EMS shifts use their own activity types.
alter table public.shift_logs drop constraint if exists shift_logs_activity_type_check;
alter table public.shift_logs add constraint shift_logs_activity_type_check check (activity_type in (
  'patrol', 'traffic', 'training', 'administrative', 'special_assignment', 'supervision',
  'fire_response', 'ems_response', 'station_duty', 'dispatch'));

-- ---------------------------------------------------------------- helpers

create or replace function public.division_of(dept text)
returns text language sql stable security definer set search_path = public as $$
  select division from public.departments where key = dept
$$;

-- Does the caller hold command over this department: an active membership in an oversight
-- department whose `oversees` includes the department's division, or in that oversight
-- department itself?
create or replace function public.oversees(dept text)
returns boolean language sql stable security definer set search_path = public as $$
  select dept is not null and exists (
    select 1 from public.memberships m join public.departments d on d.key = m.department_key
    where m.profile_id = auth.uid() and m.status = 'active' and d.kind = 'oversight'
      and (d.key = dept or public.division_of(dept) = any(d.oversees)))
$$;

-- is_dps() keeps its meaning of "holds any division command". It now gates only
-- district-wide items (district announcements and policies), never a department's records.

create or replace function public.can_read_department(dept text)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_member_of(dept) or public.oversees(dept)
$$;

create or replace function public.can_supervise(dept text)
returns boolean language sql stable security definer set search_path = public as $$
  select public.has_tier(dept, 'supervisor') or public.oversees(dept)
$$;

create or replace function public.can_view_personnel(dept text)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.memberships m join public.departments d on d.key = m.department_key
    where m.profile_id = auth.uid() and m.status = 'active'
      and ((m.department_key = dept and (public.tier_rank(m.tier) >= public.tier_rank('department_head') or m.can_view_personnel))
        or (d.kind = 'oversight' and m.can_view_personnel and public.division_of(dept) = any(d.oversees)))
  )
$$;

create or replace function public.can_manage_roster(dept text)
returns boolean language sql stable security definer set search_path = public as $$
  select public.has_tier(dept, 'high_command') or public.oversees(dept) or public.is_admin()
$$;

-- ----------------------------------------------------------- row security

drop policy profiles_supervised on public.profiles;
create policy profiles_supervised on public.profiles for select using (
  public.is_admin() or exists (
    select 1 from public.memberships m
    where m.profile_id = profiles.id and m.status in ('active', 'pending', 'suspended')
      and public.can_supervise(m.department_key)
  )
);

drop policy announcements_members on public.announcements;
create policy announcements_members on public.announcements for select to authenticated using (
  (status = 'published' and (
     (scope = 'district' and public.is_active_member() and (
        public.is_dps() or exists (select 1 from public.memberships m where m.profile_id = auth.uid()
          and m.status = 'active' and public.tier_rank(m.tier) >= public.tier_rank(announcements.audience_min_tier))))
     or (scope = 'department' and public.has_tier(department_key, audience_min_tier))
     or (scope = 'department' and public.oversees(department_key))
     or (is_public and public_approved_at is not null)))
  or (status <> 'published' and (
     (scope = 'district' and public.is_dps())
     or (scope = 'department' and (public.oversees(department_key) or public.has_tier(department_key, 'high_command')))))
);

drop policy policies_read on public.policies;
create policy policies_read on public.policies for select to authenticated using (
  (status in ('approved', 'superseded') and public.is_active_member()
     and (department_key is null or public.can_read_department(department_key)))
  or (department_key is null and public.is_dps())
  or public.oversees(department_key)
  or (department_key is not null and public.has_tier(department_key, 'high_command'))
);

drop policy policy_acks_own on public.policy_acknowledgments;
create policy policy_acks_own on public.policy_acknowledgments for select using (
  profile_id = auth.uid() or exists (
    select 1 from public.policies pol where pol.id = policy_acknowledgments.policy_id
      and ((pol.department_key is null and public.is_dps())
        or public.oversees(pol.department_key)
        or public.has_tier(pol.department_key, 'high_command')))
);

drop policy audit_read on public.audit_log;
create policy audit_read on public.audit_log for select using (
  public.is_admin()
  or (department_key is null and public.is_dps())
  or public.oversees(department_key)
  or (department_key is not null and public.has_tier(department_key, 'department_head'))
);

-- ----------------------------------------------- workflows, now division-scoped

create or replace function public.can_decide(dept text, needed public.tier)
returns boolean language sql stable security definer set search_path = public as $$
  select public.oversees(dept)
      or (needed <> 'dps' and public.has_tier(dept, needed))
$$;

create or replace function public.reviewers_for(dept text, needed public.tier, exclude uuid)
returns setof uuid language sql stable security definer set search_path = public as $$
  select distinct m.profile_id from public.memberships m join public.departments d on d.key = m.department_key
  where m.status = 'active' and m.profile_id is not null and m.profile_id <> coalesce(exclude, '00000000-0000-0000-0000-000000000000')
    and ((m.department_key = dept and needed <> 'dps' and public.tier_rank(m.tier) >= public.tier_rank(needed))
      or (d.kind = 'oversight' and public.division_of(dept) = any(d.oversees) and public.tier_rank(needed) >= public.tier_rank('department_head')))
$$;

create or replace function public.request_membership(p_department text, p_note text default null)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  d public.departments;
  new_id uuid;
begin
  select * into d from public.departments where key = p_department and active;
  if d.key is null then perform public.d5_raise('D5404', 'Department not found.'); end if;
  if d.kind = 'oversight' then perform public.d5_raise('D5403', 'Command memberships are assigned by division command.'); end if;
  if exists (select 1 from public.memberships where profile_id = p.id and department_key = p_department
             and status in ('pending', 'active', 'suspended')) then
    perform public.d5_raise('D5409', 'You already have a membership or request for this department.');
  end if;
  insert into public.memberships (profile_id, display_name, department_key, status, tier, is_probationary, request_note)
  values (p.id, p.display_name, p_department, 'pending', 'probationary', true, left(p_note, 600))
  returning id into new_id;
  insert into public.approval_actions (record_type, record_id, department_key, submitter_id, actor_id, actor_name, action, to_status, reason)
  values ('membership', new_id, p_department, p.id, p.id, p.display_name, 'submitted', 'pending', left(p_note, 600));
  perform public.notify(r, 'Roster request · ' || p.display_name, 'New ' || d.short_name || ' membership request.',
                        '/hub/roster?dept=' || p_department, 'roster', 'normal', p_department, 'membership', new_id, 'mbreq:' || new_id)
  from public.reviewers_for(p_department, 'high_command', p.id) r;
  perform public.write_audit(p, 'membership.requested', 'membership', new_id, null, p_department);
  return new_id;
end;
$$;

create or replace function public.decide_membership(
  p_membership uuid, p_action text, p_rank uuid default null, p_callsign text default null,
  p_badge text default null, p_reason text default null)
returns public.memberships language plpgsql security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  m public.memberships;
  r public.ranks;
begin
  select * into m from public.memberships where id = p_membership for update;
  if m.id is null then perform public.d5_raise('D5404', 'Membership not found.'); end if;
  if not public.can_manage_roster(m.department_key) then perform public.d5_raise('D5403', 'High command authority is required to decide roster requests.'); end if;
  if m.profile_id = p.id then perform public.d5_raise('D5403', 'You cannot approve your own roster request.'); end if;
  if m.status <> 'pending' then perform public.d5_raise('D5409', 'This request was already decided.'); end if;

  if p_action = 'approve' then
    select * into r from public.ranks where id = p_rank and department_key = m.department_key and active;
    if r.id is null then perform public.d5_raise('D5422', 'Choose a rank from this department''s ladder.'); end if;
    -- only division command or admin may grant department_head or higher; nobody grants above their own tier
    if public.tier_rank(r.tier) >= public.tier_rank('department_head') and not (public.oversees(m.department_key) or public.is_admin()) then
      perform public.d5_raise('D5403', 'Only division command can appoint department heads.');
    end if;
    if not (public.oversees(m.department_key) or public.is_admin()) and public.tier_rank(r.tier) >= public.tier_rank(public.my_tier(m.department_key)) then
      perform public.d5_raise('D5403', 'You cannot appoint someone at or above your own tier.');
    end if;
    update public.memberships set status = 'active', rank_id = r.id, rank_name = r.name, tier = r.tier,
      callsign = nullif(trim(p_callsign), ''), badge = nullif(trim(p_badge), ''),
      is_probationary = (r.tier = 'probationary'), join_date = coalesce(join_date, current_date)
    where id = m.id returning * into m;
    insert into public.personnel_records (membership_id, department_key, category, title, after_value, created_by, created_by_name)
    values (m.id, m.department_key, 'roster_change', 'Added to roster as ' || r.name,
            jsonb_build_object('rank', r.name, 'callsign', m.callsign, 'badge', m.badge), p.id, p.display_name);
  elsif p_action = 'deny' then
    if length(trim(coalesce(p_reason, ''))) < 5 then perform public.d5_raise('D5422', 'A denial needs a reason.'); end if;
    update public.memberships set status = 'denied' where id = m.id returning * into m;
  else
    perform public.d5_raise('D5422', 'Unknown action.');
  end if;

  insert into public.approval_actions (record_type, record_id, record_ref, department_key, submitter_id, actor_id, actor_name, actor_tier, action, from_status, to_status, reason)
  values ('membership', m.id, m.ref, m.department_key, m.profile_id, p.id, p.display_name, public.my_tier(m.department_key),
          case when p_action = 'approve' then 'approved' else 'denied' end, 'pending', m.status::text, p_reason);
  if m.profile_id is not null then
    perform public.notify(m.profile_id,
      case when p_action = 'approve' then 'Welcome to ' || upper(m.department_key) else 'Roster request denied' end,
      coalesce(p_reason, case when p_action = 'approve' then 'You are on the roster as ' || m.rank_name || '.' end),
      '/hub/roster/' || m.id, 'roster', 'high', m.department_key, 'membership', m.id, null);
  end if;
  perform public.write_audit(p, 'membership.' || p_action, 'membership', m.id, m.ref, m.department_key, null, to_jsonb(m));
  return m;
end;
$$;

create or replace function public.update_membership(
  p_membership uuid, p_rank uuid default null, p_callsign text default null, p_badge text default null,
  p_status public.membership_status default null, p_leave_until date default null, p_clear_leave boolean default false,
  p_supervisor uuid default null, p_training_officer uuid default null, p_subdivisions text[] default null,
  p_can_view_personnel boolean default null, p_reason text default null)
returns public.memberships language plpgsql security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  m public.memberships;
  before_m public.memberships;
  r public.ranks;
  personnel_change boolean := false;
begin
  select * into m from public.memberships where id = p_membership for update;
  if m.id is null then perform public.d5_raise('D5404', 'Membership not found.'); end if;
  before_m := m;
  if not public.can_manage_roster(m.department_key) then perform public.d5_raise('D5403', 'High command authority is required to change the roster.'); end if;
  if m.profile_id = p.id and not public.is_admin() then perform public.d5_raise('D5403', 'Another commander must change your own membership.'); end if;
  if m.status in ('pending', 'denied') then perform public.d5_raise('D5409', 'Decide the roster request first.'); end if;
  if length(trim(coalesce(p_reason, ''))) < 3 then perform public.d5_raise('D5422', 'Give a short reason for the change.'); end if;

  if p_rank is not null and p_rank is distinct from m.rank_id then
    select * into r from public.ranks where id = p_rank and department_key = m.department_key and active;
    if r.id is null then perform public.d5_raise('D5422', 'Choose a rank from this department''s ladder.'); end if;
    if public.tier_rank(r.tier) >= public.tier_rank('department_head') and not (public.oversees(m.department_key) or public.is_admin()) then
      perform public.d5_raise('D5403', 'Only division command can appoint department heads.');
    end if;
    if not (public.oversees(m.department_key) or public.is_admin()) and public.tier_rank(r.tier) >= public.tier_rank(public.my_tier(m.department_key)) then
      perform public.d5_raise('D5403', 'You cannot promote someone to or above your own tier.');
    end if;
    m.rank_id := r.id; m.rank_name := r.name; m.tier := r.tier; m.is_probationary := (r.tier = 'probationary');
    personnel_change := true;
  end if;
  if p_status is not null and p_status is distinct from m.status then
    if p_status not in ('active', 'suspended', 'removed') then perform public.d5_raise('D5422', 'Invalid status.'); end if;
    m.status := p_status;
    if p_status <> 'active' then m.duty_status := 'off_duty'; end if;
    personnel_change := true;
  end if;
  if p_can_view_personnel is not null and p_can_view_personnel is distinct from m.can_view_personnel then
    if not (public.oversees(m.department_key) or public.has_tier(m.department_key, 'department_head')) then
      perform public.d5_raise('D5403', 'Only a department head or division command can grant personnel-record access.');
    end if;
    m.can_view_personnel := p_can_view_personnel;
    personnel_change := true;
  end if;
  if p_callsign is not null then m.callsign := nullif(trim(p_callsign), ''); end if;
  if p_badge is not null then m.badge := nullif(trim(p_badge), ''); end if;
  if p_clear_leave then m.leave_until := null; elsif p_leave_until is not null then m.leave_until := p_leave_until; end if;
  if p_supervisor is not null then m.supervisor_id := p_supervisor; end if;
  if p_training_officer is not null then m.training_officer_id := p_training_officer; end if;
  if p_subdivisions is not null then m.subdivisions := p_subdivisions; end if;

  update public.memberships set rank_id = m.rank_id, rank_name = m.rank_name, tier = m.tier, is_probationary = m.is_probationary,
    status = m.status, duty_status = m.duty_status, can_view_personnel = m.can_view_personnel, callsign = m.callsign,
    badge = m.badge, leave_until = m.leave_until, supervisor_id = m.supervisor_id,
    training_officer_id = m.training_officer_id, subdivisions = m.subdivisions
  where id = m.id returning * into m;

  insert into public.personnel_records (membership_id, department_key, category, title, detail, before_value, after_value, created_by, created_by_name)
  values (m.id, m.department_key,
    case when before_m.tier is distinct from m.tier and public.tier_rank(m.tier) > public.tier_rank(before_m.tier) then 'promotion'
         when before_m.tier is distinct from m.tier then 'demotion'
         when before_m.rank_id is distinct from m.rank_id then 'rank_change'
         when before_m.status is distinct from m.status then 'status_change'
         when before_m.leave_until is distinct from m.leave_until then 'leave'
         else 'roster_change' end,
    coalesce(case when before_m.rank_id is distinct from m.rank_id then coalesce(before_m.rank_name, '—') || ' → ' || m.rank_name end,
             case when before_m.status is distinct from m.status then 'Status: ' || before_m.status || ' → ' || m.status end,
             'Roster details updated'),
    p_reason,
    jsonb_build_object('rank', before_m.rank_name, 'tier', before_m.tier, 'status', before_m.status, 'callsign', before_m.callsign, 'badge', before_m.badge, 'leave_until', before_m.leave_until),
    jsonb_build_object('rank', m.rank_name, 'tier', m.tier, 'status', m.status, 'callsign', m.callsign, 'badge', m.badge, 'leave_until', m.leave_until),
    p.id, p.display_name);

  if m.profile_id is not null and personnel_change then
    perform public.notify(m.profile_id, 'Your ' || upper(m.department_key) || ' membership changed',
      coalesce(m.rank_name, '') || ' · ' || m.status::text, '/hub/roster/' || m.id, 'roster', 'high', m.department_key, 'membership', m.id, null);
  end if;
  perform public.write_audit(p, 'membership.updated', 'membership', m.id, m.ref, m.department_key, to_jsonb(before_m), to_jsonb(m));
  return m;
end;
$$;

create or replace function public.decide_shift_log(p_id uuid, p_action text, p_reason text default null)
returns public.shift_logs language plpgsql security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  s public.shift_logs;
  was public.approval_status;
  reviewer_tier public.tier;
begin
  -- row lock serializes concurrent reviewers; the loser sees the new status below
  select * into s from public.shift_logs where id = p_id for update;
  if s.id is null then perform public.d5_raise('D5404', 'Shift log not found.'); end if;
  if s.profile_id = p.id then perform public.d5_raise('D5403', 'You cannot review your own submission. Another reviewer must decide it.'); end if;
  if not public.can_decide(s.department_key, s.required_tier) then
    perform public.d5_raise('D5403', 'This needs a ' || replace(s.required_tier::text, '_', ' ') || ' or above in ' || upper(s.department_key) || ', or DPS.');
  end if;
  if s.status not in ('submitted', 'under_review') then
    perform public.d5_raise('D5409', 'This shift log was already ' || s.status || ' by ' || coalesce(s.decided_by_name, 'another reviewer') || '.');
  end if;
  if p_action in ('deny', 'return') and length(trim(coalesce(p_reason, ''))) < 5 then
    perform public.d5_raise('D5422', case when p_action = 'deny' then 'A denial needs a reason the member can act on.' else 'Say what needs correcting.' end);
  end if;

  was := s.status;
  reviewer_tier := coalesce(public.my_tier(s.department_key), case when public.oversees(s.department_key) then 'dps'::public.tier end);
  if p_action = 'approve' then
    update public.shift_logs set status = 'approved', decided_at = now(), decided_by = p.id, decided_by_name = p.display_name,
      decision_reason = nullif(trim(coalesce(p_reason, '')), ''), version = version + 1 where id = s.id returning * into s;
  elsif p_action = 'deny' then
    update public.shift_logs set status = 'denied', decided_at = now(), decided_by = p.id, decided_by_name = p.display_name,
      decision_reason = p_reason, version = version + 1 where id = s.id returning * into s;
  elsif p_action = 'return' then
    update public.shift_logs set status = 'returned', decided_at = now(), decided_by = p.id, decided_by_name = p.display_name,
      decision_reason = p_reason, version = version + 1 where id = s.id returning * into s;
  elsif p_action = 'escalate' then
    if s.required_tier = 'dps' then perform public.d5_raise('D5409', 'This is already with DPS.'); end if;
    update public.shift_logs set status = 'under_review', required_tier = 'dps', assigned_to = null,
      decision_reason = nullif(trim(coalesce(p_reason, '')), ''), version = version + 1 where id = s.id returning * into s;
  elsif p_action = 'claim' then
    update public.shift_logs set status = 'under_review', assigned_to = p.id, version = version + 1 where id = s.id returning * into s;
  else
    perform public.d5_raise('D5422', 'Unknown action.');
  end if;

  insert into public.approval_actions (record_type, record_id, record_ref, department_key, submitter_id, actor_id, actor_name, actor_tier, action, from_status, to_status, reason)
  values ('shift_log', s.id, s.ref, s.department_key, s.profile_id, p.id, p.display_name, reviewer_tier,
          case p_action when 'approve' then 'approved' when 'deny' then 'denied' when 'return' then 'returned'
                        when 'escalate' then 'escalated' else 'claimed' end,
          was::text, s.status::text, p_reason);

  if p_action in ('approve', 'deny', 'return') then
    perform public.notify(s.profile_id,
      'Shift log ' || case p_action when 'approve' then 'approved' when 'deny' then 'denied' else 'returned for correction' end || ' · ' || s.ref,
      coalesce(p_reason, round(s.duration_minutes / 60.0, 1) || 'h counted toward this week.'),
      '/hub/shifts/' || s.id, 'approval', case when p_action = 'approve' then 'normal' else 'high' end,
      s.department_key, 'shift_log', s.id, null);
  elsif p_action = 'escalate' then
    perform public.notify(r, 'Escalated to DPS · ' || s.ref, coalesce(p_reason, s.snapshot_name), '/hub/shifts/' || s.id,
      'approval', 'high', s.department_key, 'shift_log', s.id, 'shiftesc:' || s.id)
    from public.reviewers_for(s.department_key, 'dps', s.profile_id) r;
  end if;
  perform public.write_audit(p, 'shift.' || p_action, 'shift_log', s.id, s.ref, s.department_key,
    jsonb_build_object('status', was), jsonb_build_object('status', s.status, 'reason', p_reason));
  return s;
end;
$$;

create or replace function public.save_announcement(
  p_id uuid, p_title text, p_body text, p_scope text, p_department text, p_priority text,
  p_audience_min_tier public.tier, p_pinned boolean, p_publish boolean)
returns public.announcements language plpgsql security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  a public.announcements;
begin
  if p_id is not null then
    select * into a from public.announcements where id = p_id for update;
    if a.id is null then perform public.d5_raise('D5404', 'Announcement not found.'); end if;
    -- authority comes from the stored record; scope cannot change after creation
    p_scope := a.scope; p_department := a.department_key;
  end if;
  if p_scope not in ('district', 'department') then perform public.d5_raise('D5422', 'Unknown scope.'); end if;
  if p_scope = 'district' and not public.is_dps() then perform public.d5_raise('D5403', 'District announcements are published by division command.'); end if;
  if p_scope = 'department' and not (public.has_tier(p_department, 'high_command') or public.oversees(p_department)) then
    perform public.d5_raise('D5403', 'High command authority is required to publish department announcements.');
  end if;
  if p_id is null then
    insert into public.announcements (title, body, scope, department_key, priority, audience_min_tier, pinned, status, published_at, author_id, author_name)
    values (p_title, coalesce(p_body, ''), p_scope, case when p_scope = 'department' then p_department end, coalesce(p_priority, 'normal'),
            coalesce(p_audience_min_tier, 'probationary'), coalesce(p_pinned, false),
            case when p_publish then 'published' else 'draft' end, case when p_publish then now() end, p.id, p.display_name)
    returning * into a;
  else
    update public.announcements set title = p_title, body = coalesce(p_body, ''), priority = coalesce(p_priority, priority),
      audience_min_tier = coalesce(p_audience_min_tier, audience_min_tier), pinned = coalesce(p_pinned, pinned),
      status = case when p_publish then 'published' else status end,
      published_at = case when p_publish and published_at is null then now() else published_at end
    where id = a.id returning * into a;
  end if;
  perform public.write_audit(p, case when p_publish then 'announcement.published' else 'announcement.saved' end, 'announcement', a.id, a.ref, a.department_key);
  return a;
end;
$$;

create or replace function public.set_announcement_public(p_id uuid, p_public boolean)
returns public.announcements language plpgsql security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  a public.announcements;
begin
  select * into a from public.announcements where id = p_id for update;
  if a.id is null then perform public.d5_raise('D5404', 'Announcement not found.'); end if;
  if not ((a.scope = 'district' and public.is_dps()) or public.oversees(a.department_key) or (a.scope = 'department' and public.has_tier(a.department_key, 'department_head'))) then
    perform public.d5_raise('D5403', 'A department head or division command must approve public content.');
  end if;
  if p_public and a.status <> 'published' then perform public.d5_raise('D5409', 'Publish it internally before approving it for the public site.'); end if;
  update public.announcements set is_public = p_public,
    public_approved_by = case when p_public then p.id end, public_approved_at = case when p_public then now() end
  where id = a.id returning * into a;
  perform public.write_audit(p, case when p_public then 'announcement.public_approved' else 'announcement.public_removed' end, 'announcement', a.id, a.ref, a.department_key);
  return a;
end;
$$;

create or replace function public.save_policy(
  p_id uuid, p_title text, p_category text, p_department text, p_version text, p_summary text,
  p_body text, p_source_url text, p_requires_ack boolean, p_effective date, p_approve boolean)
returns public.policies language plpgsql security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  pol public.policies;
begin
  if p_id is not null then
    select * into pol from public.policies where id = p_id for update;
    if pol.id is null then perform public.d5_raise('D5404', 'Policy not found.'); end if;
    p_department := pol.department_key;
  end if;
  if p_department is null and not public.is_dps() then perform public.d5_raise('D5403', 'District policies are managed by division command.'); end if;
  if p_department is not null and not (public.has_tier(p_department, 'department_head') or public.oversees(p_department)) then
    perform public.d5_raise('D5403', 'A department head or division command manages department policies.');
  end if;
  if p_id is null then
    insert into public.policies (title, category, department_key, version, summary, body, source_url, requires_acknowledgment, effective_date, status, approved_by, approved_at)
    values (p_title, coalesce(p_category, 'sop'), p_department, coalesce(p_version, '1.0'), p_summary, p_body, p_source_url, coalesce(p_requires_ack, false), p_effective,
            case when p_approve then 'approved' else 'draft' end, case when p_approve then p.id end, case when p_approve then now() end)
    returning * into pol;
  else
    update public.policies set title = p_title, category = coalesce(p_category, category), version = coalesce(p_version, version),
      summary = p_summary, body = p_body, source_url = p_source_url, requires_acknowledgment = coalesce(p_requires_ack, requires_acknowledgment),
      effective_date = p_effective, status = case when p_approve then 'approved' else status end,
      approved_by = case when p_approve then p.id else approved_by end, approved_at = case when p_approve then now() else approved_at end
    where id = pol.id returning * into pol;
  end if;
  perform public.write_audit(p, 'policy.saved', 'policy', pol.id, pol.ref, pol.department_key);
  return pol;
end;
$$;

create or replace function public.admin_add_roster_member(
  p_department text, p_display_name text, p_discord_id text, p_rank uuid, p_callsign text, p_badge text, p_join_date date)
returns public.memberships language plpgsql security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  r public.ranks;
  m public.memberships;
  linked uuid;
begin
  if not public.can_manage_roster(p_department) then perform public.d5_raise('D5403', 'High command authority is required.'); end if;
  select * into r from public.ranks where id = p_rank and department_key = p_department;
  if r.id is null then perform public.d5_raise('D5422', 'Choose a rank from this department''s ladder.'); end if;
  if public.tier_rank(r.tier) >= public.tier_rank('department_head') and not (public.oversees(p_department) or public.is_admin()) then
    perform public.d5_raise('D5403', 'Only division command can appoint department heads.');
  end if;
  select id into linked from public.profiles where discord_id = nullif(trim(p_discord_id), '');
  insert into public.memberships (profile_id, display_name, department_key, rank_id, rank_name, tier, callsign, badge, status, is_probationary, join_date, request_note)
  values (linked, p_display_name, p_department, r.id, r.name, r.tier, nullif(trim(p_callsign), ''), nullif(trim(p_badge), ''), 'active',
          r.tier = 'probationary', coalesce(p_join_date, current_date), case when linked is null then 'discord:' || nullif(trim(p_discord_id), '') end)
  returning * into m;
  perform public.write_audit(p, 'membership.added', 'membership', m.id, m.ref, m.department_key, null, to_jsonb(m));
  return m;
end;
$$;


-- policy helpers, so anonymous policy checks must be able to evaluate them too
revoke execute on function public.division_of(text), public.oversees(text) from public;
grant execute on function public.division_of(text), public.oversees(text) to anon, authenticated;

-- ===== supabase/migrations/20261027000006_reports_requests.sql
-- Reports, requests, training and live boards, modelled on the SAHP portal and the
-- combined forms, for every division. One `submissions` table holds every report and
-- request; each kind has its own required fields, checked in submission_check().
-- Approval side effects (certifications, subdivisions, leave) happen in the same
-- transaction as the decision.

-- DPS seats cover LEO and Fire/EMS operations, so DPS oversees every division.
-- Fire/EMS Administration remains SAFD and SAEMS's own command.
update public.departments set oversees = '{leo,fire_ems,dispatch}' where key = 'dps';

-- DPS ladder as listed on the SAHP portal roster (E-01 to E-06). Still samples until confirmed.
update public.ranks set name = 'Commissioner of DPS', abbreviation = 'E-01', sort_order = 60 where department_key = 'dps' and name = 'Commissioner';
update public.ranks set name = 'Deputy Commissioner of DPS', abbreviation = 'E-02', sort_order = 50 where department_key = 'dps' and name = 'Deputy Commissioner';
update public.ranks set name = 'Assistant Commissioner of DPS', abbreviation = 'E-03', sort_order = 40 where department_key = 'dps' and name = 'Assistant Commissioner';
update public.ranks set name = 'Captain of DPS', abbreviation = 'E-04', sort_order = 30 where department_key = 'dps' and name = 'DPS Captain';
update public.ranks set name = 'Officer of LEO Operations', abbreviation = 'E-05', sort_order = 20 where department_key = 'dps' and name = 'DPS Officer';
-- Existing databases only; fresh installs get the same rows from seed.sql.
insert into public.ranks (department_key, name, abbreviation, tier, sort_order)
select 'dps', 'Officer of Fire/EMS Operations', 'E-06', 'dps', 10
where exists (select 1 from public.departments where key = 'dps')
on conflict (department_key, name) do nothing;
update public.memberships m set rank_name = r.name from public.ranks r where m.rank_id = r.id and m.department_key = 'dps';

-- ------------------------------------------------- certifications & subdivisions

-- What each department offers. Administrators edit these; closed options refuse new requests.
create table public.department_options (
  id uuid primary key default gen_random_uuid(),
  department_key text not null references public.departments(key),
  kind text not null check (kind in ('certification', 'subdivision')),
  name text not null check (length(name) between 1 and 60),
  description text check (length(description) <= 300),
  min_tier public.tier not null default 'probationary',
  is_open boolean not null default true,
  sort_order int not null default 0,
  active boolean not null default true,
  unique (department_key, kind, name)
);

create table public.member_certifications (
  id uuid primary key default gen_random_uuid(),
  membership_id uuid not null references public.memberships(id),
  department_key text not null references public.departments(key),
  name text not null,
  granted_at timestamptz not null default now(),
  granted_by uuid references public.profiles(id),
  granted_by_name text,
  source_submission uuid,
  revoked_at timestamptz
);
create unique index member_certifications_one on public.member_certifications (membership_id, name) where revoked_at is null;

-- ---------------------------------------------------------- submissions

create sequence public.ref_submission;

create table public.submissions (
  id uuid primary key default gen_random_uuid(),
  ref text not null unique default ('D5-RQ-' || lpad(nextval('public.ref_submission')::text, 5, '0')),
  kind text not null check (kind in (
    'incident', 'use_of_force', 'fire_incident', 'patient_care',
    'warrant', 'bolo', 'certification', 'subdivision', 'leave', 'fto_log')),
  department_key text not null references public.departments(key),
  profile_id uuid not null references public.profiles(id),
  membership_id uuid not null references public.memberships(id),
  snapshot_name text not null,
  snapshot_rank text,
  snapshot_tier public.tier not null,
  snapshot_callsign text,
  snapshot_badge text,
  title text not null check (length(title) between 1 and 140),
  details jsonb not null default '{}' check (jsonb_typeof(details) = 'object' and length(details::text) <= 20000),
  evidence_url text check (evidence_url is null or evidence_url ~* '^https?://'),
  occurred_on date,
  expires_at timestamptz,
  subject_membership uuid references public.memberships(id),
  status public.approval_status not null default 'draft',
  required_tier public.tier not null default 'supervisor',
  assigned_to uuid references public.profiles(id),
  submitted_at timestamptz,
  decided_at timestamptz,
  decided_by uuid references public.profiles(id),
  decided_by_name text,
  decision_reason text,
  version int not null default 1,
  is_demo boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index submissions_queue on public.submissions (department_key, status, required_tier);
create index submissions_mine on public.submissions (profile_id, created_at desc);
create index submissions_active on public.submissions (kind, status, expires_at) where kind in ('warrant', 'bolo');
create trigger submissions_touch before update on public.submissions for each row execute function public.touch_updated_at();

alter table public.approval_actions drop constraint if exists approval_actions_action_check;
alter table public.approval_actions add constraint approval_actions_action_check check (action in (
  'created', 'submitted', 'resubmitted', 'claimed', 'assigned', 'approved', 'denied',
  'returned', 'escalated', 'withdrawn', 'commented', 'archived'));

-- Use of force goes straight to department heads; subdivision applications to high command.
insert into public.approval_routes (record_type, department_key, submitter_tier, required_tier) values
  ('use_of_force', null, 'probationary', 'department_head'),
  ('use_of_force', null, 'patrol', 'department_head'),
  ('use_of_force', null, 'supervisor', 'department_head'),
  ('use_of_force', null, 'high_command', 'department_head'),
  ('subdivision', null, 'probationary', 'high_command'),
  ('subdivision', null, 'patrol', 'high_command'),
  ('subdivision', null, 'supervisor', 'high_command')
on conflict do nothing;

-- Which kinds each division files.
create or replace function public.kind_allowed(p_kind text, p_division text)
returns boolean language sql immutable as $$
  select case p_division
    when 'leo' then p_kind in ('incident', 'use_of_force', 'warrant', 'bolo', 'certification', 'subdivision', 'leave', 'fto_log')
    when 'fire_ems' then p_kind in ('fire_incident', 'patient_care', 'certification', 'subdivision', 'leave', 'fto_log')
    when 'dispatch' then p_kind in ('certification', 'leave')
    else false
  end
$$;

-- An active member of any department in this division.
create or replace function public.in_division(p_division text)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.memberships m join public.departments d on d.key = m.department_key
                 where m.profile_id = auth.uid() and m.status = 'active' and d.division = p_division)
$$;

-- -------------------------------------------------------------- validation

create or replace function public.d5_text(j jsonb, k text)
returns text language sql immutable as $$ select nullif(trim(coalesce(j ->> k, '')), '') $$;

-- Required fields and allowed values for each kind. Raises D5422 with a message the member can act on.
create or replace function public.submission_check(
  p_kind text, p_department text, m public.memberships, j jsonb, p_evidence text,
  p_occurred date, p_expires timestamptz, p_subject uuid)
returns void language plpgsql stable security definer set search_path = public as $$
declare
  need text[];
  k text;
  opt public.department_options;
  subj public.memberships;
  label jsonb := '{"location":"location","incident_type":"incident type","summary":"summary","force_type":"type of force",
    "scene":"scene description","subject_name":"subject name","charges":"offense or charges","probable_cause":"probable cause",
    "subject":"subject or vehicle","description":"description","reason":"reason","requested":"what you are requesting",
    "why":"why you are requesting it","meets_requirements":"whether you meet the requirements","start_date":"start date",
    "end_date":"end date","complaint":"chief complaint","treatment":"treatment given","disposition":"disposition",
    "notes":"ride-along notes","recommendation":"recommendation"}';
begin
  need := case p_kind
    when 'incident' then array['location', 'incident_type', 'summary']
    when 'use_of_force' then array['force_type', 'scene']
    when 'fire_incident' then array['location', 'incident_type', 'summary']
    when 'patient_care' then array['location', 'complaint', 'treatment', 'disposition']
    when 'warrant' then array['subject_name', 'charges', 'probable_cause']
    when 'bolo' then array['subject', 'description', 'reason']
    when 'certification' then array['requested', 'why', 'meets_requirements']
    when 'subdivision' then array['requested', 'why']
    when 'leave' then array['start_date', 'end_date', 'reason']
    when 'fto_log' then array['notes', 'recommendation']
  end;
  foreach k in array need loop
    if public.d5_text(j, k) is null then
      perform public.d5_raise('D5422', 'Add the ' || coalesce(label ->> k, replace(k, '_', ' ')) || '.');
    end if;
  end loop;

  if p_kind in ('incident', 'use_of_force', 'fire_incident', 'patient_care', 'fto_log') then
    if p_occurred is null then perform public.d5_raise('D5422', 'Add the date it happened.'); end if;
    if p_occurred > current_date + 1 then perform public.d5_raise('D5422', 'The date cannot be in the future.'); end if;
  end if;
  if p_kind = 'incident' and j ->> 'incident_type' not in ('Traffic Stop', 'Arrest', 'Pursuit', 'Disturbance', 'Other') then
    perform public.d5_raise('D5422', 'Choose an incident type from the list.');
  end if;
  if p_kind = 'use_of_force' then
    if j ->> 'force_type' not in ('Verbal', 'Physical', 'Less lethal', 'Lethal') then
      perform public.d5_raise('D5422', 'Choose the type of force from the list.');
    end if;
    if p_evidence is null then perform public.d5_raise('D5422', 'Use of force reports need a video evidence link.'); end if;
  end if;
  if p_kind = 'fire_incident' and j ->> 'incident_type' not in
     ('Structure fire', 'Vehicle fire', 'Brush fire', 'Rescue', 'Medical assist', 'Hazmat', 'Other') then
    perform public.d5_raise('D5422', 'Choose an incident type from the list.');
  end if;
  if p_kind = 'patient_care' and j ->> 'disposition' not in
     ('Transported', 'Treated and released', 'Refused care', 'Deceased on scene') then
    perform public.d5_raise('D5422', 'Choose a disposition from the list.');
  end if;
  if p_kind in ('warrant', 'bolo') then
    if p_expires is null then perform public.d5_raise('D5422', 'Add the requested expiration.'); end if;
    if p_expires <= now() then perform public.d5_raise('D5422', 'The expiration must be in the future.'); end if;
    if p_expires > now() + interval '90 days' then perform public.d5_raise('D5422', 'Requests can last at most 90 days.'); end if;
  end if;
  if p_kind in ('certification', 'subdivision') then
    select * into opt from public.department_options
     where department_key = p_department and kind = p_kind and name = j ->> 'requested' and active;
    if opt.id is null then perform public.d5_raise('D5422', 'Choose a ' || p_kind || ' this department offers.'); end if;
    if not opt.is_open then perform public.d5_raise('D5409', opt.name || ' is closed to new requests right now.'); end if;
    if public.tier_rank(m.tier) < public.tier_rank(opt.min_tier) then
      perform public.d5_raise('D5403', opt.name || ' requires ' || replace(opt.min_tier::text, '_', ' ') || ' or above.');
    end if;
    if p_kind = 'certification' and exists (select 1 from public.member_certifications
        where membership_id = m.id and name = opt.name and revoked_at is null) then
      perform public.d5_raise('D5409', 'You already hold ' || opt.name || '.');
    end if;
    if p_kind = 'subdivision' and opt.name = any(m.subdivisions) then
      perform public.d5_raise('D5409', 'You are already in ' || opt.name || '.');
    end if;
    if p_kind = 'certification' and j ->> 'meets_requirements' not in ('Yes', 'No') then
      perform public.d5_raise('D5422', 'Answer whether you meet the requirements.');
    end if;
  end if;
  if p_kind = 'leave' then
    begin
      if (j ->> 'end_date')::date < (j ->> 'start_date')::date then
        perform public.d5_raise('D5422', 'Leave must end on or after its start date.');
      end if;
      if (j ->> 'end_date')::date > current_date + 180 then
        perform public.d5_raise('D5422', 'Leave can be requested at most 180 days ahead.');
      end if;
    exception when invalid_datetime_format or datetime_field_overflow then
      perform public.d5_raise('D5422', 'Use valid start and end dates.');
    end;
  end if;
  if p_kind = 'fto_log' then
    if j ->> 'recommendation' not in ('Continue training', 'Ready for release', 'Needs remediation') then
      perform public.d5_raise('D5422', 'Choose a recommendation from the list.');
    end if;
    select * into subj from public.memberships where id = p_subject;
    if subj.id is null or subj.department_key <> p_department or subj.status <> 'active' then
      perform public.d5_raise('D5422', 'Choose the probationary member you rode with.');
    end if;
    if not (subj.is_probationary or subj.tier = 'probationary') then
      perform public.d5_raise('D5422', subj.display_name || ' is not probationary.');
    end if;
    if subj.profile_id = m.profile_id then perform public.d5_raise('D5403', 'You cannot evaluate yourself.'); end if;
    if not (public.tier_rank(m.tier) >= public.tier_rank('supervisor') or exists (
        select 1 from public.member_certifications c where c.membership_id = m.id and c.revoked_at is null and c.name ilike 'FTO%')) then
      perform public.d5_raise('D5403', 'FTO logs are filed by certified FTOs or supervisors.');
    end if;
  end if;
end;
$$;

-- A short list title, so queues are readable without opening every entry.
create or replace function public.submission_title(p_kind text, j jsonb, subj_name text)
returns text language sql immutable as $$
  select left(case p_kind
    when 'incident' then j ->> 'incident_type' || ' · ' || coalesce(j ->> 'location', '')
    when 'use_of_force' then j ->> 'force_type' || ' force'
    when 'fire_incident' then j ->> 'incident_type' || ' · ' || coalesce(j ->> 'location', '')
    when 'patient_care' then coalesce(j ->> 'complaint', 'Patient care') || ' · ' || coalesce(j ->> 'disposition', '')
    when 'warrant' then 'Warrant · ' || coalesce(j ->> 'subject_name', '')
    when 'bolo' then 'BOLO · ' || coalesce(j ->> 'subject', '')
    when 'certification' then 'Certification · ' || coalesce(j ->> 'requested', '')
    when 'subdivision' then 'Subdivision · ' || coalesce(j ->> 'requested', '')
    when 'leave' then 'Leave · ' || coalesce(j ->> 'start_date', '') || ' to ' || coalesce(j ->> 'end_date', '')
    when 'fto_log' then 'FTO log · ' || coalesce(subj_name, '')
  end, 140)
$$;

-- ------------------------------------------------------------ workflows

create or replace function public.save_submission(
  p_id uuid, p_kind text, p_department text, p_details jsonb, p_evidence_url text,
  p_occurred_on date, p_expires_at timestamptz, p_subject uuid, p_submit boolean,
  p_expected_version int default null)
returns public.submissions language plpgsql security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  m public.memberships;
  d public.departments;
  s public.submissions;
  was public.approval_status;
  j jsonb;
  subj_name text;
  ev text := nullif(trim(coalesce(p_evidence_url, '')), '');
begin
  if p_id is not null then
    select * into s from public.submissions where id = p_id for update;
    if s.id is null then perform public.d5_raise('D5404', 'Not found.'); end if;
    if s.profile_id <> p.id then perform public.d5_raise('D5403', 'You can only edit your own submissions.'); end if;
    if s.status not in ('draft', 'returned') then perform public.d5_raise('D5409', 'This was already submitted and can no longer be edited.'); end if;
    if p_expected_version is not null and p_expected_version <> s.version then
      perform public.d5_raise('D5409', 'This entry changed in another window. Reload to see the latest version.');
    end if;
    -- kind and department come from the stored record
    p_kind := s.kind; p_department := s.department_key;
  end if;

  select * into m from public.memberships where profile_id = p.id and department_key = p_department and status = 'active';
  if m.id is null then perform public.d5_raise('D5403', 'You do not hold an active membership in ' || upper(coalesce(p_department, '')) || '.'); end if;
  select * into d from public.departments where key = p_department;
  if d.kind <> 'department' or not public.kind_allowed(p_kind, d.division) then
    perform public.d5_raise('D5422', upper(p_department) || ' does not file this kind of record.');
  end if;
  if ev is not null and ev !~* '^https?://' then perform public.d5_raise('D5422', 'Evidence links must start with http:// or https://.'); end if;

  -- keep only string values, trimmed
  select coalesce(jsonb_object_agg(key, left(trim(value), 4000)) filter (where trim(value) <> ''), '{}')
    into j from jsonb_each_text(coalesce(p_details, '{}'));
  if p_submit then
    perform public.submission_check(p_kind, p_department, m, j, ev, p_occurred_on, p_expires_at, p_subject);
  end if;
  select display_name into subj_name from public.memberships where id = p_subject and department_key = p_department;

  if p_id is null then
    insert into public.submissions (kind, department_key, profile_id, membership_id, snapshot_name, snapshot_rank, snapshot_tier,
      snapshot_callsign, snapshot_badge, title, details, evidence_url, occurred_on, expires_at, subject_membership,
      status, required_tier, submitted_at)
    values (p_kind, p_department, p.id, m.id, m.display_name, m.rank_name, m.tier, m.callsign, m.badge,
      coalesce(nullif(public.submission_title(p_kind, j, subj_name), ''), initcap(replace(p_kind, '_', ' '))),
      j, ev, p_occurred_on, p_expires_at, case when subj_name is not null then p_subject end,
      (case when p_submit then 'submitted' else 'draft' end)::public.approval_status,
      public.required_tier_for(p_kind, p_department, m.tier), case when p_submit then now() end)
    returning * into s;
    was := null;
  else
    was := s.status;
    update public.submissions set
      snapshot_name = m.display_name, snapshot_rank = m.rank_name, snapshot_tier = m.tier,
      snapshot_callsign = m.callsign, snapshot_badge = m.badge,
      title = coalesce(nullif(public.submission_title(p_kind, j, subj_name), ''), s.title),
      details = j, evidence_url = ev, occurred_on = p_occurred_on, expires_at = p_expires_at,
      subject_membership = case when subj_name is not null then p_subject end,
      status = case when p_submit then 'submitted'::public.approval_status else s.status end,
      submitted_at = case when p_submit then now() else s.submitted_at end,
      required_tier = public.required_tier_for(p_kind, p_department, m.tier),
      decision_reason = case when p_submit and s.status = 'returned' then null else s.decision_reason end,
      version = s.version + 1
    where id = s.id returning * into s;
  end if;

  if p_submit then
    insert into public.approval_actions (record_type, record_id, record_ref, department_key, submitter_id, actor_id, actor_name, actor_tier, action, from_status, to_status)
    values ('submission', s.id, s.ref, s.department_key, p.id, p.id, p.display_name, m.tier,
            case when was = 'returned' then 'resubmitted' else 'submitted' end, was::text, 'submitted');
    perform public.notify(r, 'To review · ' || s.title, s.ref || ' · ' || s.snapshot_name,
      '/hub/reports/' || s.id, 'approval', case when s.kind = 'use_of_force' then 'high' else 'normal' end,
      s.department_key, 'submission', s.id, 'subsub:' || s.id || ':' || s.version)
    from public.reviewers_for(s.department_key, s.required_tier, p.id) r;
  end if;
  perform public.write_audit(p, 'submission.' || case when p_submit then 'submitted' else 'saved' end, 'submission', s.id, s.ref, s.department_key);
  return s;
end;
$$;

create or replace function public.withdraw_submission(p_id uuid, p_reason text default null)
returns public.submissions language plpgsql security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  s public.submissions;
  was public.approval_status;
begin
  select * into s from public.submissions where id = p_id for update;
  if s.id is null then perform public.d5_raise('D5404', 'Not found.'); end if;
  if s.profile_id <> p.id then perform public.d5_raise('D5403', 'You can only withdraw your own submissions.'); end if;
  if s.status not in ('draft', 'submitted', 'under_review', 'returned') then
    perform public.d5_raise('D5409', 'A decided submission cannot be withdrawn.');
  end if;
  was := s.status;
  update public.submissions set status = 'withdrawn', decision_reason = nullif(trim(coalesce(p_reason, '')), ''), version = version + 1
  where id = s.id returning * into s;
  insert into public.approval_actions (record_type, record_id, record_ref, department_key, submitter_id, actor_id, actor_name, action, from_status, to_status, reason)
  values ('submission', s.id, s.ref, s.department_key, p.id, p.id, p.display_name, 'withdrawn', was::text, 'withdrawn', p_reason);
  perform public.write_audit(p, 'submission.withdrawn', 'submission', s.id, s.ref, s.department_key);
  return s;
end;
$$;

-- Approve, deny, return, escalate or claim a submission; 'archive' clears an approved
-- warrant or BOLO (served, found, or no longer needed).
create or replace function public.decide_submission(p_id uuid, p_action text, p_reason text default null)
returns public.submissions language plpgsql security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  s public.submissions;
  m public.memberships;
  was public.approval_status;
  reviewer_tier public.tier;
begin
  select * into s from public.submissions where id = p_id for update;
  if s.id is null then perform public.d5_raise('D5404', 'Not found.'); end if;
  if s.profile_id = p.id then perform public.d5_raise('D5403', 'You cannot review your own submission. Another reviewer must decide it.'); end if;

  if p_action = 'archive' then
    if s.kind not in ('warrant', 'bolo') or s.status <> 'approved' then
      perform public.d5_raise('D5409', 'Only an active warrant or BOLO can be cleared.');
    end if;
    if not public.can_supervise(s.department_key) then perform public.d5_raise('D5403', 'A supervisor must clear it.'); end if;
  else
    if not public.can_decide(s.department_key, s.required_tier) then
      perform public.d5_raise('D5403', 'This needs a ' || replace(s.required_tier::text, '_', ' ') || ' or above in ' || upper(s.department_key) || ', or division command.');
    end if;
    if s.status not in ('submitted', 'under_review') then
      perform public.d5_raise('D5409', 'This was already ' || s.status || ' by ' || coalesce(s.decided_by_name, 'another reviewer') || '.');
    end if;
  end if;
  if p_action in ('deny', 'return') and length(trim(coalesce(p_reason, ''))) < 5 then
    perform public.d5_raise('D5422', case when p_action = 'deny' then 'A denial needs a reason the member can act on.' else 'Say what needs correcting.' end);
  end if;

  was := s.status;
  reviewer_tier := coalesce(public.my_tier(s.department_key), case when public.oversees(s.department_key) then 'dps'::public.tier end);
  if p_action = 'approve' then
    update public.submissions set status = 'approved', decided_at = now(), decided_by = p.id, decided_by_name = p.display_name,
      decision_reason = nullif(trim(coalesce(p_reason, '')), ''), version = version + 1 where id = s.id returning * into s;
    select * into m from public.memberships where id = s.membership_id for update;
    if s.kind = 'certification' then
      insert into public.member_certifications (membership_id, department_key, name, granted_by, granted_by_name, source_submission)
      values (m.id, m.department_key, s.details ->> 'requested', p.id, p.display_name, s.id)
      on conflict do nothing;
    elsif s.kind = 'subdivision' and not (s.details ->> 'requested' = any(m.subdivisions)) then
      update public.memberships set subdivisions = array_append(subdivisions, s.details ->> 'requested') where id = m.id;
    elsif s.kind = 'leave' then
      update public.memberships set leave_until = greatest(coalesce(leave_until, (s.details ->> 'end_date')::date), (s.details ->> 'end_date')::date)
      where id = m.id;
    end if;
    if s.kind in ('certification', 'subdivision', 'leave') then
      insert into public.personnel_records (membership_id, department_key, category, title, after_value, created_by, created_by_name)
      values (m.id, m.department_key, case s.kind when 'leave' then 'leave' when 'certification' then 'certification' else 'roster_change' end,
              s.title || ' approved', s.details, p.id, p.display_name);
    end if;
  elsif p_action = 'deny' then
    update public.submissions set status = 'denied', decided_at = now(), decided_by = p.id, decided_by_name = p.display_name,
      decision_reason = p_reason, version = version + 1 where id = s.id returning * into s;
  elsif p_action = 'return' then
    update public.submissions set status = 'returned', decided_at = now(), decided_by = p.id, decided_by_name = p.display_name,
      decision_reason = p_reason, version = version + 1 where id = s.id returning * into s;
  elsif p_action = 'escalate' then
    if s.required_tier = 'dps' then perform public.d5_raise('D5409', 'This is already with division command.'); end if;
    update public.submissions set status = 'under_review', required_tier = 'dps', assigned_to = null,
      decision_reason = nullif(trim(coalesce(p_reason, '')), ''), version = version + 1 where id = s.id returning * into s;
  elsif p_action = 'claim' then
    update public.submissions set status = 'under_review', assigned_to = p.id, version = version + 1 where id = s.id returning * into s;
  elsif p_action = 'archive' then
    update public.submissions set status = 'archived', decision_reason = coalesce(nullif(trim(coalesce(p_reason, '')), ''), decision_reason),
      version = version + 1 where id = s.id returning * into s;
  else
    perform public.d5_raise('D5422', 'Unknown action.');
  end if;

  insert into public.approval_actions (record_type, record_id, record_ref, department_key, submitter_id, actor_id, actor_name, actor_tier, action, from_status, to_status, reason)
  values ('submission', s.id, s.ref, s.department_key, s.profile_id, p.id, p.display_name, reviewer_tier,
          case p_action when 'approve' then 'approved' when 'deny' then 'denied' when 'return' then 'returned'
                        when 'escalate' then 'escalated' when 'archive' then 'archived' else 'claimed' end,
          was::text, s.status::text, p_reason);

  if p_action in ('approve', 'deny', 'return', 'archive') then
    perform public.notify(s.profile_id,
      case p_action when 'approve' then 'Approved' when 'deny' then 'Denied' when 'archive' then 'Cleared' else 'Returned for correction' end || ' · ' || s.title,
      coalesce(p_reason, s.ref), '/hub/reports/' || s.id, 'approval', case when p_action = 'approve' then 'normal' else 'high' end,
      s.department_key, 'submission', s.id, null);
  elsif p_action = 'escalate' then
    perform public.notify(r, 'Escalated · ' || s.title, coalesce(p_reason, s.snapshot_name), '/hub/reports/' || s.id,
      'approval', 'high', s.department_key, 'submission', s.id, 'subesc:' || s.id)
    from public.reviewers_for(s.department_key, 'dps', s.profile_id) r;
  end if;
  perform public.write_audit(p, 'submission.' || p_action, 'submission', s.id, s.ref, s.department_key,
    jsonb_build_object('status', was), jsonb_build_object('status', s.status, 'reason', p_reason));
  return s;
end;
$$;

-- Command can revoke a certification, with a reason recorded in personnel history.
create or replace function public.revoke_certification(p_id uuid, p_reason text)
returns void language plpgsql security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  c public.member_certifications;
begin
  select * into c from public.member_certifications where id = p_id and revoked_at is null for update;
  if c.id is null then perform public.d5_raise('D5404', 'Certification not found.'); end if;
  if not public.can_manage_roster(c.department_key) then perform public.d5_raise('D5403', 'High command authority is required.'); end if;
  if length(trim(coalesce(p_reason, ''))) < 3 then perform public.d5_raise('D5422', 'Give a short reason.'); end if;
  update public.member_certifications set revoked_at = now() where id = c.id;
  insert into public.personnel_records (membership_id, department_key, category, title, detail, created_by, created_by_name)
  values (c.membership_id, c.department_key, 'certification', c.name || ' certification revoked', p_reason, p.id, p.display_name);
  perform public.write_audit(p, 'certification.revoked', 'member_certification', c.id, c.name, c.department_key);
end;
$$;

-- Top members this week by clocked time, approved and pending (denied and returned excluded).
create or replace function public.weekly_leaderboard(p_department text, p_limit int default 10)
returns table (display_name text, callsign text, rank_name text, minutes int)
language plpgsql stable security definer set search_path = public as $$
declare d public.departments;
begin
  select * into d from public.departments where key = p_department;
  if d.key is null then perform public.d5_raise('D5404', 'Department not found.'); end if;
  if not public.can_read_department(p_department) then perform public.d5_raise('D5403', 'Members only.'); end if;
  return query
    select m.display_name, m.callsign, m.rank_name, sum(s.duration_minutes)::int
    from public.shift_logs s join public.memberships m on m.id = s.membership_id
    where s.department_key = p_department and s.status in ('submitted', 'under_review', 'approved')
      and s.week_start = public.week_start_for(now(), d.timezone, d.week_starts_on)
    group by m.id, m.display_name, m.callsign, m.rank_name
    order by 4 desc, 1
    limit least(greatest(coalesce(p_limit, 10), 1), 50);
end;
$$;

-- -------------------------------------------------------------- admin

create or replace function public.admin_save_option(
  p_id uuid, p_department text, p_kind text, p_name text, p_description text,
  p_min_tier public.tier, p_open boolean, p_sort int, p_active boolean default true)
returns public.department_options language plpgsql security definer set search_path = public as $$
declare
  p public.profiles := public.require_user();
  o public.department_options;
begin
  if not public.is_admin() then perform public.d5_raise('D5403', 'Administrator access is required.'); end if;
  if p_id is null then
    insert into public.department_options (department_key, kind, name, description, min_tier, is_open, sort_order, active)
    values (p_department, p_kind, trim(p_name), nullif(trim(coalesce(p_description, '')), ''), coalesce(p_min_tier, 'probationary'),
            coalesce(p_open, true), coalesce(p_sort, 0), coalesce(p_active, true))
    returning * into o;
  else
    update public.department_options set name = trim(p_name), description = nullif(trim(coalesce(p_description, '')), ''),
      min_tier = coalesce(p_min_tier, min_tier), is_open = coalesce(p_open, is_open), sort_order = coalesce(p_sort, sort_order),
      active = coalesce(p_active, active)
    where id = p_id returning * into o;
    if o.id is null then perform public.d5_raise('D5404', 'Option not found.'); end if;
  end if;
  perform public.write_audit(p, 'option.saved', 'department_option', o.id, o.name, o.department_key);
  return o;
exception when unique_violation then
  perform public.d5_raise('D5409', 'That name is already listed for this department.');
end;
$$;

-- ----------------------------------------------------------- row security

alter table public.department_options enable row level security;
alter table public.member_certifications enable row level security;
alter table public.submissions enable row level security;

create policy options_read on public.department_options for select using (true);
-- Training records are general roster information, like rank and callsign.
create policy certifications_read on public.member_certifications for select using (public.is_active_member() or public.is_admin());

create policy submissions_own on public.submissions for select using (profile_id = auth.uid());
create policy submissions_reviewers on public.submissions for select using (
  status <> 'draft' and public.can_supervise(department_key)
);
-- Active warrants and BOLOs are shared with every active member of the division.
create policy submissions_active_alerts on public.submissions for select using (
  kind in ('warrant', 'bolo') and status = 'approved' and expires_at > now()
  and public.in_division(public.division_of(department_key))
);
-- A trainee reads decided FTO logs about themselves.
create policy submissions_fto_subject on public.submissions for select using (
  kind = 'fto_log' and status = 'approved' and exists (
    select 1 from public.memberships m where m.id = submissions.subject_membership and m.profile_id = auth.uid())
);

grant select on public.department_options, public.member_certifications, public.submissions to anon, authenticated;
revoke insert, update, delete, truncate on public.department_options, public.member_certifications, public.submissions from anon, authenticated;

revoke execute on function public.kind_allowed(text, text), public.in_division(text), public.d5_text(jsonb, text),
  public.submission_check(text, text, public.memberships, jsonb, text, date, timestamptz, uuid),
  public.submission_title(text, jsonb, text), public.save_submission(uuid, text, text, jsonb, text, date, timestamptz, uuid, boolean, int),
  public.withdraw_submission(uuid, text), public.decide_submission(uuid, text, text), public.revoke_certification(uuid, text),
  public.weekly_leaderboard(text, int), public.admin_save_option(uuid, text, text, text, text, public.tier, boolean, int, boolean)
  from public, anon;
grant execute on function public.save_submission(uuid, text, text, jsonb, text, date, timestamptz, uuid, boolean, int),
  public.withdraw_submission(uuid, text), public.decide_submission(uuid, text, text), public.revoke_certification(uuid, text),
  public.weekly_leaderboard(text, int), public.admin_save_option(uuid, text, text, text, text, public.tier, boolean, int, boolean),
  public.kind_allowed(text, text), public.submission_title(text, jsonb, text), public.d5_text(jsonb, text)
  to authenticated;
-- policy helper: anonymous policy checks must be able to evaluate it
grant execute on function public.in_division(text) to anon, authenticated;
-- internal: only called from save_submission
revoke execute on function public.submission_check(text, text, public.memberships, jsonb, text, date, timestamptz, uuid) from authenticated;

